function currentSidebarSearch(){return [...document.querySelectorAll('#search,#registry-search,#archive-search,#catalog-search,#audit-search,#p301-search')].find(el=>el.offsetParent!==null&&!el.disabled);}
function sidebarTourProgress(){try{return JSON.parse(localStorage.getItem(SIDEBAR_TOUR_KEY)||'{}')||{};}catch{return {};}}
function saveSidebarTourProgress(progress){try{localStorage.setItem(SIDEBAR_TOUR_KEY,JSON.stringify(progress));}catch{}}
function mountSidebarTour(sidebar){
 const launch=sidebar.querySelector('#sidebar-help');if(!launch)return;let overlay,highlighted,steps=[],index=0,view='dashboard',previousFocus;
 const close=()=>{highlighted?.classList.remove('tour-highlight');overlay?.remove();overlay=null;highlighted=null;previousFocus?.focus?.({preventScroll:true});};
 const show=()=>{if(!overlay)return;highlighted?.classList.remove('tour-highlight');while(index<steps.length&&!document.querySelector(steps[index][0]))index++;if(index>=steps.length){const progress=sidebarTourProgress();progress[view]={index:0,completed:true};saveSidebarTourProgress(progress);close();return;}const [selector,title,text]=steps[index],target=document.querySelector(selector);highlighted=target;target.classList.add('tour-highlight');target.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});overlay.querySelector('[data-tour-title]').textContent=title;overlay.querySelector('[data-tour-text]').textContent=text;overlay.querySelector('[data-tour-count]').textContent=`${index+1} / ${steps.length}`;overlay.querySelector('[data-tour-back]').disabled=index===0;overlay.querySelector('[data-tour-next]').textContent=index===steps.length-1?'เสร็จ':'ถัดไป';const progress=sidebarTourProgress();progress[view]={index,completed:false};saveSidebarTourProgress(progress);};
 launch.addEventListener('click',()=>{if(overlay){close();return;}view=document.querySelector('#app')?.dataset.screen||sidebar.querySelector('[data-view].active')?.dataset.view||'dashboard';steps=sidebarTourSteps[view]||sidebarTourSteps.dashboard;const saved=sidebarTourProgress()[view];index=saved&&!saved.completed?Math.min(saved.index||0,steps.length-1):0;previousFocus=document.activeElement;overlay=document.createElement('div');overlay.className='tour-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-labelledby','tour-title');overlay.innerHTML='<section class="tour-card"><div class="tour-card-top"><span data-tour-count></span><button type="button" data-tour-close aria-label="ปิดคำแนะนำ">×</button></div><h2 id="tour-title" data-tour-title></h2><p data-tour-text></p><div class="tour-actions"><button type="button" class="btn" data-tour-restart>เริ่มใหม่</button><span></span><button type="button" class="btn" data-tour-back>ย้อนกลับ</button><button type="button" class="btn primary" data-tour-next>ถัดไป</button></div></section>';document.body.append(overlay);overlay.querySelector('[data-tour-close]').onclick=close;overlay.querySelector('[data-tour-restart]').onclick=()=>{index=0;show();};overlay.querySelector('[data-tour-back]').onclick=()=>{index=Math.max(0,index-1);show();};overlay.querySelector('[data-tour-next]').onclick=()=>{index++;show();};overlay.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();close();}if(event.key==='Tab'){const focusable=[...overlay.querySelectorAll('button:not(:disabled)')],first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});show();overlay.querySelector('[data-tour-close]').focus();});
}
function mountCollapsibleSidebar(){
 const sidebar=document.querySelector('#app-sidebar');if(!sidebar||sidebar.dataset.interactionMounted)return;sidebar.dataset.interactionMounted='true';const toggle=document.querySelector('#sidebar-toggle'),mobile=window.matchMedia('(max-width:850px)'),buttons=[...sidebar.querySelectorAll('button[data-view]')];let savedCollapsed=document.documentElement.classList.contains('sidebar-is-collapsed');
 try{savedCollapsed=localStorage.getItem(SIDEBAR_COLLAPSE_KEY)==='true';}catch{}for(const button of buttons){const label=button.querySelector('.nav-text')?.textContent.trim()||button.getAttribute('aria-label')||'';button.setAttribute('aria-label',label);button.title=label;}
 function applyState(){const collapsed=!mobile.matches&&savedCollapsed;const mobileClosed=mobile.matches&&!sidebar.classList.contains('open');sidebar.classList.toggle('is-collapsed',collapsed);document.documentElement.classList.toggle('sidebar-is-collapsed',collapsed);sidebar.toggleAttribute('inert',mobileClosed);sidebar.setAttribute('aria-hidden',String(mobileClosed));toggle.setAttribute('aria-expanded',String(!collapsed));toggle.setAttribute('aria-label',mobile.matches?'ปิดเมนู':collapsed?'ขยายเมนู':'ย่อเมนู');toggle.title=toggle.getAttribute('aria-label');requestAnimationFrame(()=>window.dispatchEvent(new Event('resize')));}
 function setCollapsed(value){savedCollapsed=value;try{localStorage.setItem(SIDEBAR_COLLAPSE_KEY,String(value));}catch{}applyState();}
 document.querySelector('#mobile-menu')?.addEventListener('click',event=>{event.stopImmediatePropagation();const open=!sidebar.classList.contains('open');sidebar.classList.toggle('open',open);applyState();if(open)sidebar.querySelector('#sidebar-toggle')?.focus();},true);
 toggle.addEventListener('click',()=>{if(mobile.matches){sidebar.classList.remove('open');applyState();document.querySelector('#mobile-menu')?.focus();}else setCollapsed(!savedCollapsed);});document.addEventListener('keydown',event=>{if(event.isComposing||event.altKey||event.repeat||document.querySelector('#modal')?.open||document.querySelector('.tour-overlay'))return;if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){const search=currentSidebarSearch();if(search){event.preventDefault();search.focus({preventScroll:true});search.select?.();}}if(event.key==='Escape'&&mobile.matches&&sidebar.classList.contains('open')){sidebar.classList.remove('open');applyState();document.querySelector('#mobile-menu')?.focus();}});mobile.addEventListener('change',()=>{sidebar.classList.remove('open');applyState();});sidebar.addEventListener('transitionend',event=>{if(event.target===sidebar&&event.propertyName==='width')window.dispatchEvent(new Event('resize'));});mountSidebarTour(sidebar);applyState();
}
if(typeof document!=='undefined')mountCollapsibleSidebar();
// ==================== 1. DATA MODEL AND BUSINESS RULES ====================
export const clone=o=>JSON.parse(JSON.stringify(o));
// Import history is immutable during ordinary edits and can be several MB.
export function cloneForMutation(s){const {importHistory,...active}=s;return {...clone(active),...(importHistory===undefined?{}:{importHistory})};}
export function workspaceChanges(before,after){
 const collections={},values={};
 for(const k of ['projects','reports','contractRegistry','categories','contractors','supervisors','workTypes','workNames','workCodes','budgetAccounts','fundingSources']){
  const old=new Map((before[k]||[]).map(x=>[x.id,x])),now=new Map((after[k]||[]).map(x=>[x.id,x]));
  const upsert=[...now.values()].filter(x=>!x._unloaded&&old.get(x.id)!==x&&JSON.stringify(old.get(x.id))!==JSON.stringify(x));const remove=[...old.keys()].filter(id=>!now.has(id));
  if(upsert.length||remove.length)collections[k]={upsert,remove};
 }
 const settings=Object.fromEntries(Object.entries(after.settings||{}).filter(([key,value])=>JSON.stringify(before.settings?.[key])!==JSON.stringify(value)));if(Object.keys(settings).length)values.settings=settings;
 for(const k of ['years','yearCodes','masterSequences','issues'])if(JSON.stringify(before[k])!==JSON.stringify(after[k])&&after[k]!==undefined)values[k]=after[k];
 return {collections,values};
}
export function validateLoadedWorkspace(s){if(!s||typeof s!=='object'||!Array.isArray(s.projects)||!Array.isArray(s.reports))throw Error('ข้อมูลจากฐานข้อมูลมีโครงสร้างไม่ครบ กรุณาโหลดใหม่โดยไม่เขียนทับข้อมูลบนอุปกรณ์');if(!s.loadedScope)return validateBackup(s);const reports=s.reports.filter(r=>r&&!r._unloaded);return validateBackup({...s,reports:reports.length?reports:[{id:'EMPTY',entries:{},snapshots:{},locked:true,imported:true}]});}
const qualityCache=new WeakMap();
export function qualityIssues(s,year,funding){const key=year+'|'+funding,cached=qualityCache.get(s);if(cached?.has(key))return cached.get(key);const result=computeQualityIssues(s,year,funding);const cache=cached||new Map();cache.set(key,result);qualityCache.set(s,cache);return result;}
function computeQualityIssues(s,year,funding){const rows=[],gaps=new Map();const scoped=s.reports.filter(r=>reportMatchesScope(s,r,year,funding));const periods=new Map();
 for(const r of scoped){const key=r.start+'|'+r.end;if(r.start&&r.end){if(periods.has(key))rows.push({type:'รอบวันที่ซ้ำตามต้นฉบับ',label:r.title,reportId:r.id,evidence:[r.start,r.end]});else periods.set(key,r.id);if(days(r.end,r.start)!==6||new Date(r.end+'T00:00:00Z').getUTCDay()!==1)rows.push({type:'ช่วงรายงานต้องตรวจสอบ',label:r.title,reportId:r.id,evidence:[r.start,r.end]});}
  for(const [id,e]of missingPaymentDates(r)){const p=projectAt(s,r,id);const key=p?.contract||id,existing=gaps.get(key);if(existing){existing.count++;existing.evidence.push([r.id,e.payment,e.paymentDate||'',e.note||'']);}else gaps.set(key,{type:'วันที่เบิกจ่ายไม่ครบ',label:key,reportId:r.id,count:1,evidence:[[r.id,e.payment,e.paymentDate||'',e.note||'']]});}
 }
 for(const x of gaps.values())rows.push({...x,label:x.label+' · พบใน '+x.count+' รายงาน'});
 for(const r of s.contractRegistry||[])if(!r.deletedAt&&r.year===year&&(r.funding||'DOH')===funding&&(!r.contractorId||r.contractorNeedsReview))rows.push({type:'ผู้รับจ้างรอตรวจสอบ',label:r.contract+' · '+r.title,registryId:r.id,evidence:[r.contractorRaw||'',r.contractorId||'',!!r.contractorNeedsReview]});
 const contractorsList=s.contractors||[],byContractorKey=new Map();for(const c of contractorsList){for(const n of [c.name,...(c.aliases||[])]){const k=contractorNameKey(n);if(k){let arr=byContractorKey.get(k);if(!arr){arr=[];byContractorKey.set(k,arr);}arr.push(c);}}}for(const c of contractorsList){const k=contractorNameKey(c.name),exact=(byContractorKey.get(k)||[]).find(x=>x.id!==c.id);let target=exact;if(!target&&contractorsList.length<=250){const suggestions=contractorCandidates({...s,contractors:contractorsList.filter(x=>x.id!==c.id)},c.name);target=suggestions.matches[0]||suggestions.suggestions.find(x=>x.score>=.95);}if(target)rows.push({type:'ชื่อผู้รับจ้างซ้ำหรือใกล้เคียง · ข้อมูลร่วมทุกปี',label:c.name+' → '+target.name,contractorId:c.id,evidence:[c.id,target.id,c.name,target.name]});}
 for(const r of s.contractRegistry||[])if(!r.deletedAt&&r.year===year&&(r.funding||'DOH')===funding){for(const warning of r.warnings||[])rows.push({type:'ข้อควรตรวจสอบจากไฟล์',label:r.contract+' · '+warning,registryId:r.id,evidence:[warning]});if(r.end&&r.start&&r.end<r.start)rows.push({type:'วันสิ้นสุดก่อนวันเริ่มสัญญา',label:r.contract,registryId:r.id,evidence:[r.start,r.end]});}
 return rows;
}
export const missingPaymentDates=r=>r._missingPaymentDates||Object.entries(r.entries||{}).filter(([,e])=>e.payment==='เบิกจ่ายแล้ว'&&!e.paymentDate);
export function reportMatchesScope(s,r,year,funding){if(r.id==='EMPTY'||(r.funding||'DOH')!==funding)return false;if(r.year)return r.year===year;return Object.keys(r.entries||{}).some(id=>(r.snapshots?.[id]||s.projects.find(p=>p.id===id))?.year===year);}

export const uid=()=>globalThis.crypto?.randomUUID?.()||'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=(globalThis.crypto?.getRandomValues?.(new Uint8Array(1))[0]??Math.random()*16)&15;return(c==='x'?r:(r&3|8)).toString(16);});
export const iso=d=>new Date(d).toISOString().slice(0,10);
export const addDays=(d,n)=>iso(Date.parse(d+'T00:00:00Z')+n*86400000);
export const days=(a,b)=>Math.round((Date.parse(a+'T00:00:00Z')-Date.parse(b+'T00:00:00Z'))/86400000);
export const today=()=>{const p=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}`;};
export function rangeFor(date,mode='tue'){let dow=new Date(date+'T00:00:00Z').getUTCDay();let monday=addDays(date,-((dow+6)%7));return mode==='tue'?{start:addDays(monday,-6),end:monday,reference:monday}:{start:monday,end:addDays(monday,6),reference:monday};}
export const complete=e=>Number(e.actual)===100;
export function p301WorkflowStatus(data){return data.status==='exempt'?'exempt':data.status==='ready'&&!data.issues?.length?(data.confirmed?'done':'ready'):'pending';}
export const elapsed=(p,e,reference)=>complete(e)?'-':Math.max(0,days(reference,p.start)+1);
export const extensionDayDelta=e=>{if(!e?.approved)return 0;const days=Number(e.days)||0;return e.type==='reduce'||e.type==='ลด'?-Math.abs(days):Math.abs(days);};
export const effectiveDays=p=>(Number(p.duration)||0)+(p.extensions||[]).reduce((n,e)=>n+extensionDayDelta(e),0);
export const effectiveEnd=p=>{const base=p.originalEnd||p.end;if(!base)return '';return addDays(base,(p.extensions||[]).reduce((n,e)=>n+extensionDayDelta(e),0));};
export function recalculateExtensionChain(record,extensions=record.extensions||[]){
 const ordered=extensions.map((entry,index)=>({...entry,sequence:Number(entry.sequence)||index+1})).sort((a,b)=>a.sequence-b.sequence);
 const originalEnd=record.originalEnd||record.extensions?.find(x=>x.previousEnd)?.previousEnd||record.end;
 let end=originalEnd;
 for(const entry of ordered){entry.previousEnd=end;end=addDays(end,extensionDayDelta(entry));entry.end=end;}
 return {...record,originalEnd,extensions:ordered,end};
}
export const expired=(p,date=today())=>!!effectiveEnd(p)&&date>effectiveEnd(p);
export const entryFor=(report,id)=>report.entries[id]||{plan:0,weekly:0,actual:0,note:'',payment:'รอส่งมอบงาน',confirmed:false};
export function validateEntry(e,previous){if(!e||typeof e!=='object'||Array.isArray(e))throw Error('ข้อมูลผลงานไม่ถูกต้อง');for(const k of ['plan','weekly','actual'])if(!Number.isFinite(Number(e[k]))||Number(e[k])<0||Number(e[k])>100)throw Error('เปอร์เซ็นต์ต้องเป็นตัวเลขระหว่าง 0–100');if(previous&&Number(e.actual)<Number(previous.actual))throw Error('ผลงานสะสมลดลงจากรอบก่อน กรุณาตรวจสอบ');if(previous&&Math.abs(Number(e.actual)-Number(previous.actual)-Number(e.weekly))>.011)throw Error('ผลงานสะสมต้องเท่ากับผลงานสะสมรอบก่อน + ผลงานรายสัปดาห์');if(e.payment&&!['รอส่งมอบงาน','รอเบิกจ่าย','เบิกจ่ายแล้ว'].includes(e.payment))throw Error('สถานะเบิกจ่ายไม่ถูกต้อง');if(e.payment==='เบิกจ่ายแล้ว'&&!complete(e))throw Error('เบิกจ่ายแล้วต้องมีผลงานสะสม 100%');}
export function projectAt(state,report,id){const p=report.snapshots?.[id]||state.projects.find(p=>p.id===id);if(!p)return p;const names=effectiveReportNames(state,report,p),registry=!report.locked?state.contractRegistry?.find(r=>r.projectId===id):null,primary=registry?principalSupervisor(state,registry):null;return {...p,title:names.title||p.title,contractor:names.contractor??p.contractor,supervisor:names.supervisor??(registry?(primary?shortSupervisor(primary.name):''):p.supervisor)};}
export function rowsFor(state,report,year){return Object.keys(report.entries).map(id=>({p:projectAt(state,report,id),e:report.entries[id]})).filter(x=>x.p&&(!year||x.p.year===Number(year))&&(!state.activeFunding||(x.p.funding||'DOH')===state.activeFunding)).sort(sortRows);}

export function reportLinkAudit(s,r,year=r.year,funding=r.funding||'DOH'){
 const registry=registryRecords(s,year,funding),projects=new Map(s.projects.map(p=>[p.id,p])),byRegistry=new Map(registry.map(x=>[x.id,x])),byProject=new Map(registry.filter(x=>x.projectId).map(x=>[x.projectId,x])),groups=new Map(),missing=[],unresolved=[],outside=[];
 for(const id of Object.keys(r.entries||{})){const p=r.snapshots?.[id]||projects.get(id),reg=byProject.get(id)||byRegistry.get(p?.registryId);if(!p){unresolved.push(id);continue;}if(+p.year!==+year||(p.funding||'DOH')!==funding){outside.push(id);continue;}if(reg){const ids=groups.get(reg.id)||[];ids.push(id);groups.set(reg.id,ids);}}
 for(const reg of registry)if(!groups.has(reg.id))missing.push(reg);
 return {registryCount:registry.length,entryCount:Object.keys(r.entries||{}).length,visibleCount:rowsFor({...s,activeFunding:funding},r,year).length,linkedCount:groups.size,missing,duplicates:[...groups].filter(([,ids])=>ids.length>1).map(([id,ids])=>({id,ids})),unresolved,outside};
}
export function fillMissingReportContracts(s,reportId,{automatic=false}={}){
 const r=s.reports.find(x=>x.id===reportId);if(!r||r.id==='EMPTY')throw Error('กรุณาสร้างรายงานก่อน');if(r._unloaded)throw Error('กรุณาโหลดรายงานให้ครบก่อนเชื่อมโยง');if(r.locked&&!automatic)throw Error('รายงานปิดแล้ว กรุณาสร้างสัปดาห์ใหม่เพื่อดึงสัญญาที่เพิ่มภายหลัง');
 if(!automatic&&s.reports.some(x=>x.id!==r.id&&x.year===r.year&&(x.funding||'DOH')===(r.funding||'DOH')&&x.end>r.end))throw Error('เติมสัญญาได้เฉพาะฉบับร่างล่าสุด');
 const audit=reportLinkAudit(s,r);if(audit.duplicates.length||audit.unresolved.length||audit.outside.length)throw Error('พบรายการซ้ำหรืออ้างอิงไม่สมบูรณ์ กรุณาตรวจรายการก่อนดึงข้อมูล');
 if(!audit.missing.length)return 0;
 const earlier=s.reports.filter(x=>x.id!==r.id&&x.end&&x.end<r.start&&(x.funding||'DOH')===(r.funding||'DOH')&&(!x.year||x.year===r.year)).sort((a,b)=>b.end.localeCompare(a.end));
 for(const reg of audit.missing){const p=projectFromRegistry(s,reg);if(r.entries[p.id])throw Error('รหัสเชื่อมโยงชนกับรายการเดิม กรุณาตรวจทะเบียนสัญญา');reg.projectId=p.id;const i=s.projects.findIndex(x=>x.id===p.id);if(i<0)s.projects.push(p);else s.projects[i]=p;const prior=(s.loadedScope?.reportId===r.id?s.loadedScope.previousEntries?.[p.id]:undefined)||earlier.find(x=>x.entries?.[p.id])?.entries[p.id]||s.settings.reportBaselines?.[r.id]?.[p.id];
 r.entries[p.id]={...clone(prior||entryFor({entries:{}},p.id)),weekly:0,confirmed:false};if(r.locked){r.snapshots||={};r.snapshots[p.id]=clone(p);}for(const [to,from]of [['note','note'],['deliveryDate','deliveryDate'],['acceptanceDate','acceptanceDate'],['paymentDate','finalPaymentDate'],['payment','payment']])if(reg[from]!==undefined&&!(to==='payment'&&(prior||!complete(r.entries[p.id]))))r.entries[p.id][to]=reg[from];}
 r._entryCount=Object.keys(r.entries).length;if(automatic&&r.locked){r.modifiedAt=new Date().toISOString();r.amendedVersion=(r.amendedVersion||0)+1;}return audit.missing.length;
}

export function reportSettingsSnapshot(settings){const {roadSections,reportDisplayNames,reportSupervisorNames,reportContractorNames,reportNameHistory,reportBaselines,lastImportResult,yearChanges,dataReviews,depreciationCatalog,workCodeCatalog,workCodeBudgetLinks,...layout}=settings;return clone(layout);}
export function createReport(state,range,year,funding='DOH'){if(days(range.end,range.start)!==6)throw Error('รอบรายงานต้องมี 7 วัน');if(range.reference!==range.end||new Date(range.end+'T00:00:00Z').getUTCDay()!==1)throw Error('รอบอังคาร–จันทร์ต้องสิ้นสุดวันจันทร์และใช้วันท้ายรอบคำนวณ');if(state.reports.some(r=>r.start===range.start&&r.year===year&&(r.funding||'DOH')===funding&&!r.imported))throw Error('มีรอบรายงานนี้ในปีงบประมาณที่เลือกแล้ว');if(state.contractRegistry||state.projects.some(p=>p.contract))linkRegistryForReport(state,year,funding);const candidates=state.reports.filter(r=>(!r.year||r.year===year)&&(r.funding||'DOH')===funding&&r.end&&r.end<range.start).sort((a,b)=>b.end.localeCompare(a.end));const entries={};for(const p of state.projects.filter(p=>!p.deletedAt&&p.year===year&&(p.funding||'DOH')===funding)){const prev=candidates.find(r=>r.entries[p.id]);const carried=state.loadedScope?.latestEntries?.[p.id];const e=prev?entryFor(prev,p.id):carried&&state.loadedScope?.funding===funding&&state.loadedScope?.year===year&&state.reports.filter(r=>(r.funding||'DOH')===funding&&(!r.year||r.year===year)).every(r=>!r.end||r.end<range.start)?carried:{...entryFor({entries:{}},p.id),deliveryDate:state.contractRegistry?.find(x=>x.projectId===p.id)?.deliveryDate||'',acceptanceDate:state.contractRegistry?.find(x=>x.projectId===p.id)?.acceptanceDate||'',paymentDate:state.contractRegistry?.find(x=>x.projectId===p.id)?.finalPaymentDate||''};entries[p.id]={...clone(e),paymentDate:e.paymentDate||parsePaymentDate(e.note)||state.contractRegistry?.find(x=>x.projectId===p.id)?.finalPaymentDate||'',weekly:0,confirmed:false};const reg=state.contractRegistry?.find(x=>x.projectId===p.id);if(reg){for(const [target,key]of [['note','note'],['deliveryDate','deliveryDate'],['acceptanceDate','acceptanceDate'],['paymentDate','finalPaymentDate'],['payment','payment']])if(reg[key]!==undefined&&!(target==='payment'&&!complete(entries[p.id])))entries[p.id][target]=reg[key];}}if(!Object.keys(entries).length)throw Error('ไม่มีสัญญาในปีงบประมาณที่เลือก');return {id:'RPT-'+range.end+'-'+year+'-'+funding,title:'สัปดาห์ที่ '+nextWeek(state,year,funding),funding,year,...range,locked:false,imported:false,entries,snapshots:{},createdAt:new Date().toISOString()};}
export function validateProject(p,state,ignoreId){validateDates(p?.start,p?.end);if(!p.title.trim()||!p.contract.trim()||!p.start||!p.end||!p.contractor.trim())throw Error('กรอกข้อมูลงาน สัญญา หมวดหมู่ วันที่ และผู้รับจ้างให้ครบ');if(p.end<p.start)throw Error('วันสิ้นสุดสัญญาต้องไม่น้อยกว่าวันเริ่มต้น');if(!Number.isInteger(p.duration)||p.duration<=0)throw Error('ระยะเวลาดำเนินการต้องเป็นจำนวนเต็มมากกว่า 0');if(state.projects.some(x=>x.id!==ignoreId&&x.year===p.year&&x.contract===p.contract&&(x.funding||'DOH')===(p.funding||'DOH')))throw Error('เลขสัญญานี้มีอยู่แล้วในปีงบประมาณเดียวกัน');}

