export async function commitCSVForm(button,task,onError){
 const form=button.closest('form');if(form.getAttribute('aria-busy')==='true')return;const label=button.textContent,controls=[...form.querySelectorAll('button,input,select')].map(el=>[el,el.disabled]);
 form.setAttribute('aria-busy','true');for(const [el]of controls)el.disabled=true;
 let status=form.querySelector('.form-status');if(!status){status=document.createElement('p');status.className='form-status hint';status.setAttribute('role','status');status.setAttribute('aria-live','polite');form.append(status);}status.textContent='กำลังบันทึกข้อมูลที่เปลี่ยน กรุณารอสักครู่…';button.textContent='กำลังบันทึก…';
 const error=form.querySelector('.form-error');if(error)error.textContent='';
 try{await task();}catch(e){const uncertain=['AbortError','TimeoutError'].includes(e.name)||/Failed to fetch|network|fetch failed/i.test(e.message);operationFeedback('error',{problem:e,retry:uncertain?undefined:()=>button.click()});status.textContent=uncertain?'ยังยืนยันผลบันทึกไม่ได้ กรุณาตรวจข้อมูลล่าสุดก่อนนำเข้าซ้ำ':'บันทึกไม่สำเร็จ กรุณาตรวจข้อความด้านล่าง';let el=(form.id==='contract-form'?$('#modal .dialog-footer > .form-error'):null)||form.querySelector(':scope > .form-error');if(!el){el=document.createElement('p');el.className='form-error';el.setAttribute('role','alert');form.append(el);}el.textContent=e.message+(uncertain?' · ปิดหน้าต่างนี้แล้วโหลดข้อมูลล่าสุด เพื่อตรวจว่ารายการถูกบันทึกแล้วหรือไม่':'');el.tabIndex=-1;el.focus();onError?.(e);}finally{form.removeAttribute('aria-busy');for(const [el,disabled]of controls)el.disabled=disabled;button.textContent=label;}
}
