export function clearFiscalYear(s,year){const registry=s.contractRegistry.filter(r=>r.year===year),projectIds=new Set(s.projects.filter(p=>p.year===year).map(p=>p.id)),reportIds=new Set(s.reports.filter(r=>r.year===year).map(r=>r.id));for(const r of registry)if(r.projectId)projectIds.add(r.projectId);s.contractRegistry=s.contractRegistry.filter(r=>r.year!==year);s.projects=s.projects.filter(p=>!projectIds.has(p.id));s.reports=s.reports.filter(r=>!reportIds.has(r.id));for(const r of s.reports)for(const id of projectIds){delete r.entries?.[id];delete r.snapshots?.[id];}for(const key of ['reportDisplayNames','reportSupervisorNames','reportContractorNames','reportBaselines'])for(const id of Object.keys(s.settings[key]||{})){if(reportIds.has(id))delete s.settings[key][id];else for(const pid of projectIds)delete s.settings[key][id][pid];}for(const id of projectIds)delete s.settings.reportNameHistory?.[id];s.amendments=(s.amendments||[]).filter(a=>!reportIds.has(a.reportId));s.issues=(s.issues||[]).filter(x=>!reportIds.has(x.reportId)&&!projectIds.has(x.projectId));if(!s.reports.length)s.reports=[clone(BOOTSTRAP.reports[0])];return {contracts:registry.length,reports:reportIds.size,projects:projectIds.size};}
export function toProblemDetails(error,status=422,instance='/workspace'){const raw=String(error?.message||error||'บันทึกไม่สำเร็จ');let fix='ตรวจข้อมูลที่กรอก แล้วลองบันทึกอีกครั้ง',field='',type='https://pn-weekly.doh.go.th/problems/validation-error',title='ข้อมูลยังไม่ผ่านเงื่อนไขการบันทึก',code=status||422;if(/อีกหน้าจอ|revision|conflict|ข้อมูลเปลี่ยนแปลง/.test(raw)){fix='เก็บค่าที่กรอกไว้ แล้วโหลดข้อมูลล่าสุดเพื่อตรวจความขัดแย้งก่อนบันทึก';type='https://pn-weekly.doh.go.th/problems/revision-conflict';title='ข้อมูลถูกแก้ไขจากอีกหน้าจอ';code=409;}else if(/fetch|network|timeout|connection|เชื่อมต่อ|ยืนยันผล/i.test(raw)){fix='ตรวจอินเทอร์เน็ตและสถานะงานรอส่ง หากยังไม่ทราบผลให้โหลดตรวจข้อมูลก่อนกดซ้ำ';type='https://pn-weekly.doh.go.th/problems/upstream-unavailable';title='ยังส่งข้อมูลขึ้นฐานข้อมูลกลางไม่สำเร็จ';code=503;}else if(/ผู้รับจ้าง|ชื่อจากไฟล์/.test(raw)){field='contractorId';fix='เลือกผู้รับจ้างที่ถูกต้อง หากชื่อซ้ำให้ย้ายการอ้างอิงจากข้อมูลพื้นฐาน';}else if(/วันที่|วันสิ้นสุด|วันเริ่ม|ระยะเวลา/.test(raw)){field=/สิ้นสุด/.test(raw)?'end':/เริ่ม/.test(raw)?'start':'deliveryDate';fix='ตรวจวันเริ่ม–สิ้นสุด และลำดับส่งมอบ ตรวจรับ เบิกจ่าย';}else if(/ชื่อซ้ำ/.test(raw)){field='name';fix='ใช้รายการเดิม หรือเปลี่ยนชื่อให้ต่างจากรายการที่มีอยู่';}else if(/เปอร์เซ็นต์|สะสม/.test(raw)){field='actual';fix='กรอก 0–100 และให้สะสมเท่ากับรอบก่อนบวกผลงานสัปดาห์นี้';}return {type,title,status:code,detail:raw,instance,reason:raw,fix,field,timestamp:new Date().toISOString()};}
