export function knownTransferSize(headers){const total=Number(headers.get('content-length'));return headers.get('content-encoding')==='identity'&&Number.isFinite(total)&&total>0?total:0;}
export function operationFeedback(phase,{title='',detail='',progress,problem,retry}={}){
 if(typeof document==='undefined')return;
 let el=document.querySelector('#operation-feedback');if(!el){el=document.createElement('div');el.id='operation-feedback';el.setAttribute('popover','manual');document.body.append(el);document.querySelector('#modal')?.addEventListener('close',()=>{if(el.parentElement?.id==='modal'){const visible=!el.hidden;try{el.hidePopover?.();}catch{}document.body.append(el);if(visible)try{el.showPopover?.();}catch{}}});}
 clearTimeout(operationFeedback.timer);el.dataset.phase=phase;el.setAttribute('role',phase==='error'?'alert':'status');el.setAttribute('aria-live',phase==='error'?'assertive':'polite');
 const ok=phase==='success',error=phase==='error',busy=phase==='loading',info=problem?saveFailureInfo(problem):null;
 el.innerHTML='<button type="button" class="feedback-dismiss" aria-label="ปิดการแจ้งเตือน">×</button><div class="feedback-mark" aria-hidden="true">'+(busy?'<span class="feedback-spinner"></span>':ok?'<svg viewBox="0 0 52 52"><circle cx="26" cy="26" r="23"/><path d="m14 27 8 8 17-19"/></svg>':'!')+'</div><h2>'+esc(title||(ok?'บันทึกสำเร็จ':error?'บันทึกไม่สำเร็จ':'กำลังดำเนินการ'))+'</h2><p>'+esc(detail||info?.reason||'')+'</p>'+(busy?'<div class="operation-progress" role="progressbar" aria-label="ความคืบหน้า" '+(Number.isFinite(progress)?'aria-valuenow="'+Math.min(100,Math.max(0,progress))+'" aria-valuemin="0" aria-valuemax="100"':'')+'><span style="'+(Number.isFinite(progress)?'width:'+Math.min(100,Math.max(0,progress))+'%':'')+'"></span></div><small>'+(Number.isFinite(progress)?Math.floor(progress)+'%':'กำลังรอผลจากระบบ…')+'</small>':'')+(error?'<div class="feedback-fix">แนะนำ: '+esc(info?.fix||'ตรวจข้อมูลแล้วลองอีกครั้ง')+'</div><p class="hint">ค่าที่กรอกยังอยู่ กรุณาตรวจผลบันทึกก่อนส่งซ้ำหากการเชื่อมต่อขาดหาย</p>':'')+(retry?'<button type="button" class="btn primary" data-feedback-retry>ลองอีกครั้ง</button>':'');
 const close=()=>{if(el.hidePopover)try{el.hidePopover();}catch{}el.hidden=true;};
 const host=document.querySelector('#modal[open]')||document.body;if(el.parentElement!==host){try{el.hidePopover?.();}catch{}host.append(el);}el.hidden=false;if(el.showPopover){try{el.showPopover();}catch{}}
 el.querySelector('.feedback-dismiss').onclick=close;
 el.querySelector('[data-feedback-retry]')?.addEventListener('click',()=>withButtonLock(el.querySelector('[data-feedback-retry]'),async()=>{close();await retry();},e=>operationFeedback('error',{problem:e,retry})));
 if(ok)operationFeedback.timer=setTimeout(close,3500);
 return close;
}
export async function withButtonLock(btn,task,onError){if(btn?.dataset?.loading==='true')return;const wasDisabled=Boolean(btn?.disabled);if(btn){btn.disabled=true;btn.dataset.loading='true';btn.setAttribute('aria-busy','true');}try{return await task();}catch(err){if(onError)onError(err);else throw err;}finally{if(btn){delete btn.dataset.loading;btn.removeAttribute('aria-busy');btn.disabled=wasDisabled;}}}

