 const current=registryCurrent(s,r),latest=latestContractEntry(s,r),contractor=s.contractors.find(x=>x.id===r.contractorId),missing=v=>v===undefined||v===null||v==='',text=v=>esc(missing(v)?'ยังไม่ระบุ':String(v)),amount=v=>missing(v)?'ยังไม่ระบุ':money(v)+' บาท',date=v=>v?fmt(v):'ยังไม่ระบุ',days=v=>missing(v)?'ยังไม่ระบุ':text(v)+' วัน';
