 return `<article class="contract-dossier" aria-label="รายละเอียดสัญญา ${esc(r.contract)}"><header class="record-overview"><div class="record-state"><span class="pill">${esc(status)}</span>${dataChangeBadge(r)}${registryExpired(s,r)?'<span class="pill warn">หมดอายุสัญญาแล้ว</span>':''}</div><p class="record-contract">เลขสัญญา ${text(r.contract)}</p><h3 class="record-title">${text(r.title)}</h3><p class="record-identity">ID Code <strong>${text(r.sourceId)}</strong><span>รหัสงาน <strong>${text(r.workCode)}</strong></span><span>ปีงบประมาณ ${text(r.year)}</span><span>${text(fundingName(s,r.funding))}</span></p><dl class="record-summary"><div><dt>วงเงินสัญญา</dt><dd>${amount(r.contractValue)}</dd></div><div><dt>ผลงานสะสมล่าสุด</dt><dd>${progress}</dd></div><div><dt>สิ้นสุดสัญญาปัจจุบัน</dt><dd>${date(r.end)}</dd></div></dl></header><div class="record-sections">${section('รายละเอียดโครงการ',facts([['ประเภทงาน',text(s.workTypes.find(x=>x.id===r.workTypeId)?.name)],['บัญชีงบประมาณ',text(r.budgetAccount)],['บัญชีงบประมาณตามต้นฉบับ',text(r.budgetAccountSource)]]))}${section('สัญญาและระยะเวลา',facts([['ลงนามสัญญา',date(r.signedAt)],['เริ่มต้นสัญญา',date(r.start)],['สิ้นสุดเดิมก่อนขยาย',date(r.originalEnd||r.end)],['ระยะเวลาเดิม',days(r.duration)],['ขยายเวลาที่อนุมัติแล้ว',days(totalExtension)],['วันสิ้นสุดหลังขยายจากต้นฉบับ',date(r.sourceExtendedEnd)],['จำนวนวันขยายจากต้นฉบับ',days(r.sourceExtensionDays)]])+(r.extensions?.length?`<h4>ประวัติขยายสัญญา</h4><ul class="record-extensions">${r.extensions.map(x=>`<li><strong>${text(x.reference)}</strong> · ${days(x.days)} · ${x.approved?'อนุมัติแล้ว':'ยังไม่อนุมัติ'}<br>อนุมัติ ${date(x.approvedAt)} · สิ้นสุด ${date(x.end)}</li>`).join('')}</ul>`:''))}${section('งบประมาณและวงเงิน',facts([['พ.ร.บ.',amount(r.budgetAct)],['จัดสรร',amount(r.allocatedBudget)],['วงเงินสัญญา',amount(r.contractValue)],['PO',amount(r.poAmount)],['เงินกันปีถัดไป',amount(r.carryBudget)]]))}${section('การเบิกจ่าย',facts([['ภายในปีงบประมาณ',amount(r.paidFiscal)],['เบิกจ่ายเงินกันปีถัดไป',amount(r.paidCarry)],['ยอดเบิกจ่ายรวมโครงการ',amount(r.actualCost)],['เดือน / ปีจากต้นฉบับ',month],['วันที่เบิกเงินงวดสุดท้าย',date(r.finalPaymentDate)],['สถานะเบิกจ่าย',text(current.currentPayment||'ยังไม่ระบุ')],['สถานะทะเบียน',text(current.sourceStatus||'ยังไม่แล้วเสร็จ')]]))}${section('ความก้าวหน้าและการส่งมอบ',facts([['ผลงานสะสมล่าสุด',progress],['อ้างอิงรายงานล่าสุด',latest?.report?date(latest.report.end):latest?'รายงานล่าสุดของโครงการ':'ข้อมูลต้นฉบับ'],['ผลงานสะสมตามต้นฉบับ',missing(r.sourceActual)?'ยังไม่ระบุ':text(r.sourceActual)+'%'],['วันส่งมอบงาน',date(r.deliveryDate)],['วันตรวจรับงาน',date(r.acceptanceDate)]]))}${section('ผู้รับจ้างและบุคลากร',facts([['ผู้รับจ้าง',text(contractor?.name||r.contractorRaw)],...(r.contractorRaw&&r.contractorRaw!==contractor?.name?[['ชื่อจากไฟล์',text(r.contractorRaw)]]:[]),...(r.contractorNeedsReview?[['ตรวจชื่อผู้รับจ้าง','รอตรวจชื่อ']]:[])])+`<h4 class="section-title">คณะกรรมการตรวจรับพัสดุ ${personnelManageButton('inspection')}</h4>${personnelTableHTML(s,r,'inspection')}<h4 class="section-title">ผู้ควบคุมงาน ${personnelManageButton('supervision')}</h4>${personnelTableHTML(s,r,'supervision')}`)}${section('ช่วงทางและปริมาณงาน',`<div class="detail-management"></div>`+routes+`<button type="button" class="btn" id="detail-add-route" data-detail-tools hidden>+ เพิ่มสาย / ช่วงทาง</button>`+facts([['ระยะทางจริง',missing(r.distance)?'ยังไม่ระบุ':text(r.distance)+' กม.'],['ระยะทางเทียบ 2 ช่องจราจร',missing(r.twoLaneDistance)?'ยังไม่ระบุ':text(r.twoLaneDistance)+' กม.'],['ปริมาณงาน',missing(r.quantity)?'ยังไม่ระบุ':text(r.quantity)+(r.unit?' '+text(r.unit):'')],['หน่วยนับ',text(r.unit)]]),true)}${section('หมวดรหัสงานกรมทางหลวง',facts([['สำนัก / บัญชีงบประมาณ',text(r.budgetAccount||s.budgetAccounts?.find(b=>b.id===r.budgetAccountId)?.name)],['โครงการ',text(workCodePath(r.workCode).project?.name)],['กิจกรรม',text(workCodePath(r.workCode).activity?.name)],['รหัสงานทะเบียน',text(r.workCode)],['รหัสค่าเสื่อม พ.3-01',text(depreciationWorkCode(r.workCode))]]),true)}${section('หมายเหตุและข้อมูลเพิ่มเติม',`<p class="record-note">${text(current.note)}</p>`+((s.settings.customFields||[]).length?facts(s.settings.customFields.map(c=>[c.name,text(r.extras?.[c.id])])):''),true)}</div></article>`;
