async function requestOnce(name,body){
 const c=config();if(!c)throw Error('ยังไม่ได้ตั้งค่า Supabase');
 const read=/^pn2_load_/.test(name),quiet=name==='pn2_record_activity',token=Symbol(name);if(!quiet){request.close?.();request.current=token;}
 let close;const timer=setTimeout(()=>{if(!quiet&&request.current===token){close=operationFeedback('loading',{title:read?'กำลังโหลดข้อมูล':'กำลังบันทึกข้อมูล',detail:read?'กำลังรับข้อมูลล่าสุด':'กำลังส่งข้อมูลและรอฐานข้อมูลยืนยันผล'});request.close=close;}},350);
 try{
 const res=await fetch(c.url+'/rest/v1/rpc/'+name,{method:'POST',signal:AbortSignal.timeout(30000),headers:{apikey:c.key,'Content-Type':'application/json'},body:JSON.stringify(body)});
 let data;try{
 const total=knownTransferSize(res.headers);if(res.body&&total>0){const reader=res.body.getReader(),decoder=new TextDecoder();let received=0,text='';while(true){const part=await reader.read();if(part.done)break;received+=part.value.length;text+=decoder.decode(part.value,{stream:true});if(close&&request.current===token)operationFeedback('loading',{title:read?'กำลังโหลดข้อมูล':'กำลังตรวจผลบันทึก',detail:'กำลังรับข้อมูลจากระบบ',progress:Math.min(99,received/total*100)});}text+=decoder.decode();data=JSON.parse(text);}else data=await res.json();
 }catch{throw Error('Supabase ตอบกลับไม่ถูกต้อง HTTP '+res.status);}
 if(!res.ok){const message=data.message||data.error_description||'เชื่อมต่อฐานข้อมูลไม่สำเร็จ HTTP '+res.status,err=Error(/statement timeout/i.test(message)?'ฐานข้อมูลใช้เวลานานเกินกำหนด กรุณาโหลดข้อมูลล่าสุดและตรวจสถานะก่อนลองอีกครั้ง':message);err.status=res.status;err.problem=toProblemDetails(err,res.status,'/rest/v1/rpc/'+name);throw err;}
 return data;
 }catch(e){e.problem||=toProblemDetails(e,e.status||503,'/rest/v1/rpc/'+name);throw e;}
 finally{clearTimeout(timer);if(request.current===token){close?.();request.close=undefined;}}
}
