export const contractKey=v=>cleanCell(v).normalize('NFKC').replace(/^ป\s*\.?\s*น\s*\.?\s*/,'').replace(/\s/g,'').toUpperCase();
export function parseG3Date(v){if(v===null||v===undefined||v==='')return '';if(typeof v==='number'){if(!Number.isFinite(v)||v<=0||v>2958465)throw Error('วันที่ตัวเลขใน Excel ไม่ถูกต้อง');return new Date(Date.UTC(1899,11,30)+Math.floor(v)*86400000).toISOString().slice(0,10);}let text=cleanCell(v).replace(/\s+0{1,2}:00(?::00)?$/,'');if(/^\d{4}-\d{2}-\d{2}/.test(text)){const date=text.slice(0,10);if(Number.isNaN(Date.parse(date+'T00:00:00Z'))||new Date(date+'T00:00:00Z').toISOString().slice(0,10)!==date)throw Error('วันที่ไม่ถูกต้อง: '+text);return date;}const months=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];let m=text.match(/^(\d{1,2})[\s-]+([^\s]+?)[\s-]+(\d{2,4})$/),d,month,y;if(m){d=+m[1];month=months.indexOf(m[2])+1;if(!month)month=['มกราคม','กุมภาพันธ์','มีนาคม','เมษายน','พฤษภาคม','มิถุนายน','กรกฎาคม','สิงหาคม','กันยายน','ตุลาคม','พฤศจิกายน','ธันวาคม'].indexOf(m[2])+1;y=+m[3];}else{m=text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})$/);if(!m)throw Error('อ่านวันที่ไม่ได้: '+text);d=+m[1];month=+m[2];y=+m[3];}if(y<100)y+=2500;if(y>2400)y-=543;const iso=String(y)+'-'+String(month).padStart(2,'0')+'-'+String(d).padStart(2,'0');if(month<1||month>12||new Date(iso+'T00:00:00Z').toISOString().slice(0,10)!==iso)throw Error('วันที่ไม่ถูกต้อง: '+text);return iso;}
export const registryFileColumns=registryColumns.filter(([k])=>!['workspaceId','sourceRow','warnings'].includes(k));
