 const m=s.match(/(\d{1,2})\s*([^\d\s–-]*?)\s*(?:พ\.?ศ\.?\s*(\d{2,4}))?\s*[–-]\s*(\d{1,2})\s*([^\d\s–-]+)\s*(?:พ\.?ศ\.?\s*(\d{2,4}))?/);
