 if(key==='years'){s.years=s.years.filter(y=>{if(names.has(String(y))||s.projects.some(p=>p.year===y)||s.reports.some(r=>r.year===y)||s.contractRegistry.some(r=>r.year===y))return true;if(s.yearCodes)delete s.yearCodes[y];removed++;return false;});if(!s.years.length)throw Error('ต้องมีปีงบประมาณอย่างน้อยหนึ่งปี');}
 else s[key]=s[key].filter(x=>{if(keepIds.has(x.id)||names.has(x.name.toLowerCase().replace(/\s+/g,' ')))return true;if(isMasterUsed(s,key,x.id)){return true;}removed++;return false;});
