 now.name=item.name;if(item.hasPositionColumn){old.position||='';now.position=item.position;}if(item.hasAliasesColumn){old.aliases||=[];now.aliases=item.aliases;}if(item.hasNameReviewColumn){old.needsNameReview=!!old.needsNameReview;now.needsNameReview=item.needsNameReview;}if(key==='supervisors'&&item.personRoles)now.personRoles=item.personRoles;if(item.code)now.code=item.code;delete old.archived;delete now.archived;
 if(key==='contractors'){if(item.hasAddressColumn){old.address||='';now.address=item.address;}if(item.hasPhoneColumn){old.phone||='';now.phone=item.phone;}}
 if(key==='workNames'){if(item.hasTypeColumn){old.typeId||='';now.typeId=s.workTypes.find(x=>x.name===item.typeName)?.id||'';}if(item.hasCodeColumn){old.codeIds=(record?.codeIds||[]).map(id=>s.workCodes.find(c=>c.id===id)?.name||id);now.codeIds=item.codes;}}
