 const nameIndex=key==='supervisors'?head.findIndex(h=>['ชื่อบุคลากร','ชื่อผู้ควบคุมงาน','ชื่อคณะกรรมการ','ชื่อ'].includes(h)):head.indexOf(aliases[key]),addressIndex=head.indexOf('ที่อยู่'),phoneIndex=head.indexOf('เบอร์โทรศัพท์');const normalizedHead=head.map((h,i)=>i===nameIndex?'ชื่อ':h).map(h=>h==='เก็บเข้าคลัง'?'legacy_ignored_archive':h);
 const q=x=>'"'+String(x??'').replace(/"/g,'""')+'"',normalized=[normalizedHead,...table.slice(1)].map(r=>r.map(q).join(',')).join('\r\n');
 const preview=previewMasterCSVLegacy(s,key,normalized),claimed=new Map();if(key==='workNames'&&nameIndex>=0){const codeIndex=head.indexOf('รหัสงาน'),identityIndex=head.indexOf('รหัส');for(let i=0;i<preview.length;i++){const row=table[i+1];if(!String(row[nameIndex]||'').trim()&&String(row[codeIndex]||'').trim()){const lone=previewMasterCSVLegacy(s,'workCodes',[['รหัส','ชื่อ'],[row[identityIndex]||'',row[codeIndex]]].map(r=>r.map(q).join(',')).join('\r\n'))[0];lone.index=i;lone.masterKey='workCodes';if(!lone.matchId)lone.errors.push('รหัสงานใหม่ต้องระบุชื่องานด้วย');preview[i]=lone;}}}
 for(const item of preview){const row=table[item.index+1];if(key==='supervisors'&&head.includes('ตำแหน่ง')){item.hasPositionColumn=true;item.position=String(row[head.indexOf('ตำแหน่ง')]||'').trim();}if(key==='contractors'&&head.includes('ชื่อเรียกอื่น JSON')){item.hasAliasesColumn=true;try{item.aliases=JSON.parse(row[head.indexOf('ชื่อเรียกอื่น JSON')]||'[]');if(!Array.isArray(item.aliases)||item.aliases.some(x=>typeof x!=='string'))throw Error();}catch{item.errors.push('ชื่อเรียกอื่น JSON ไม่ถูกต้อง');}}if(key==='contractors'&&head.includes('รอตรวจชื่อ')){item.hasNameReviewColumn=true;item.needsNameReview=row[head.indexOf('รอตรวจชื่อ')]==='ใช่';}if(key==='supervisors'&&head.includes('บทบาท')){const value=String(row[head.indexOf('บทบาท')]||'').trim();if(value){item.personRoles=[...new Set(value.split('|').map(x=>x.trim()).map(x=>x==='คณะกรรมการตรวจรับพัสดุ'?'inspection':x==='ผู้ควบคุมงาน'?'supervision':x))];if(item.personRoles.some(x=>!['inspection','supervision'].includes(x)))item.errors.push('บทบาทบุคลากรไม่ถูกต้อง');}}if(key==='contractors'){item.hasAddressColumn=addressIndex>=0;item.hasPhoneColumn=phoneIndex>=0;item.address=String(row[addressIndex]||'').trim();item.phone=String(row[phoneIndex]||'').trim();if(item.address.length>2000)item.errors.push('ที่อยู่ยาวเกิน 2000 ตัวอักษร');if(item.phone.length>80)item.errors.push('เบอร์โทรศัพท์ยาวเกิน 80 ตัวอักษร');}
 if(key==='workNames'&&!item.masterKey){if(!item.matchId&&!item.codes.length)item.errors.push('รายการใหม่ต้องระบุรหัสงาน');for(const code of item.codes){const codeId=s.workCodes.find(c=>c.name===code)?.id,owner=s.workNames.find(w=>w.id!==item.matchId&&w.codeIds?.includes(codeId));if((owner||claimed.has(code)&&claimed.get(code)!==item.index)&&!s.workNames.find(w=>w.id===item.matchId)?.codeIds?.includes(codeId))item.errors.push('รหัสงานนี้จับคู่กับชื่องานอื่นแล้ว');claimed.set(code,item.index);}}
 }return preview;
