function historySelectedRows(){const table=$('.asset-history-table'),rows=historyRows();if(!table)return rows;const ids=selectionFor(table.dataset.selectionKey,JSON.parse(table.dataset.selectionIds));if(!ids.length)throw Error('กรุณาเลือกรายการที่จะออกรายงาน');return rows.filter(r=>ids.includes(r.id));}
