function depreciationCatalogDialog(code=''){
 let query=String(code),group='',pageNo=1;const source=state.settings.depreciationCatalog||P301_DEPRECIATION_SOURCE,rows=source.rows.filter(r=>r.life||r.asset||r.expense),groups=source.groups||[];
 modal('ตารางค่าเสื่อมราคาตามรหัสงาน',`<p class="hint">อ้างอิงชีตค่าเสื่อมราคา · แยกกลุ่มตามช่วงตารางต้นทาง · รหัสตรงกันเชื่อมกับข้อมูลพื้นฐานและ พ.3-01 อัตโนมัติ · อัตรา = 100 ÷ อายุใช้งาน</p><div class="form-grid"><label class="field">ค้นหารหัสงาน / ประเภทงาน<input type="search" id="depreciation-search" class="search" value="${esc(query)}"></label>${selectField('กลุ่มตามชีต','depreciationGroup',[{value:'',label:'ทุกกลุ่ม'},...groups.map(g=>({value:g.rows,label:g.title}))],'')}</div><div class="table-scroll"><table class="depreciation-reference-table"><thead><tr><th>รหัสงาน / ชื่องาน</th><th>ประเภทสินทรัพย์ / บัญชี</th><th>อายุใช้งาน</th><th>อัตราต่อปี</th><th>การรับรู้</th></tr></thead><tbody></tbody></table></div><div class="table-foot"><span id="depreciation-count" role="status"></span><div class="actions"><button class="btn" id="depreciation-prev">ก่อนหน้า</button><button class="btn" id="depreciation-next">ถัดไป</button></div></div>`);$('#modal').style.width='1200px';
 const paint=()=>{const bounds=group?group.split(':').map(Number):null,list=rows.filter(r=>(!bounds||r.row>=bounds[0]&&r.row<=bounds[1])&&(!query||[r.code,r.name,r.account,r.description].join(' ').toLowerCase().includes(query.toLowerCase()))),max=Math.max(1,Math.ceil(list.length/25));pageNo=Math.min(max,pageNo);let previous='';$('.depreciation-reference-table tbody').innerHTML=list.slice((pageNo-1)*25,pageNo*25).map(r=>{const g=groups.find(g=>{const [a,b]=g.rows.split(':').map(Number);return r.row>=a&&r.row<=b;}),label=g?.title||(r.row<11?'แถว 2–10':'แถว 73–85'),heading=label!==previous?'<tr class="source-group"><th colspan="5">'+esc(label)+'</th></tr>':'';previous=label;return heading+'<tr><td><strong>'+esc(r.code)+' · '+esc(r.name||'ตามรหัสงานเดียวกัน')+'</strong><details><summary>รายละเอียดงานต้นทาง</summary>'+esc(r.description||source.rows.find(x=>x.code===r.code&&x.description)?.description||'')+'</details></td><td>'+esc(r.account||source.rows.find(x=>x.code===r.code&&x.account)?.account||'–')+'</td><td>'+(r.life?r.life+' ปี':'–')+'</td><td>'+(r.life?(100/r.life).toFixed(2)+'%':'–')+'</td><td>'+(r.life?'สินทรัพย์':r.expense?'ค่าใช้จ่าย':'ยังไม่กำหนด')+'</td></tr>';}).join('')||'<tr><td colspan="5">ไม่พบรหัสงาน ลองล้างคำค้นหรือเปลี่ยนกลุ่ม</td></tr>';$('#depreciation-count').textContent=list.length+' รายการ · หน้า '+pageNo+' / '+max;$('#depreciation-prev').disabled=pageNo===1;$('#depreciation-next').disabled=pageNo===max;};
 $('#depreciation-search').oninput=e=>{query=e.target.value;pageNo=1;paint();};$('[name=depreciationGroup]').onchange=e=>{group=e.target.value;pageNo=1;paint();};$('#depreciation-prev').onclick=()=>{pageNo--;paint();};$('#depreciation-next').onclick=()=>{pageNo++;paint();};paint();
}

function p301RuleDialog(id){const master=state.workCodes.find(x=>x.id===id);if(!master)throw Error('กรุณาระบุรหัสงานในทะเบียนสัญญาก่อน');if(depreciationSourceRule(master.name))return depreciationCatalogDialog(master.name);const rule={...p301WorkRule(master.name),...master};modal('กฎสินทรัพย์ · รหัสงาน '+master.name,`<form id="p301-rule-form" novalidate><p class="hint">ใช้ร่วมกับข้อมูลพื้นฐาน ทุกสัญญาที่อ้างรหัสนี้และไม่ได้กำหนดเองจะใช้กฎเดียวกัน</p><div class="form-grid">${selectField('การรับรู้','recognitionType',[{value:'asset',label:'สินทรัพย์'},{value:'expense',label:'ค่าใช้จ่าย'}],rule.recognitionType)}${selectField('ประเภทสินทรัพย์','assetCategory',P301_CATEGORIES,rule.assetCategory)}${field('รหัสบัญชีแยกประเภท','glAccount',rule.glAccount)}${field('อายุใช้งาน (ปี)','usefulLifeYears',rule.usefulLifeYears,'number','min="0" max="100" step="1"')}${field('อัตราค่าเสื่อม (%)','depreciationRate',rule.depreciationRate,'number','min="0" max="100" step="0.01"')}${field('ลักษณะเริ่มต้น','defaultFeature',rule.defaultFeature)}</div><div class="dialog-actions"><button type="submit" class="btn primary">บันทึกกฎรหัสงาน</button></div></form>`,async values=>withButtonLock($('#p301-rule-form [type=submit]'),async()=>mutate('ตั้งค่ากฎสินทรัพย์ '+master.name,s=>{const target=s.workCodes.find(x=>x.id===id),next=Object.fromEntries(values);next.usefulLifeYears=Number(next.usefulLifeYears);next.depreciationRate=Number(next.depreciationRate);Object.assign(target,next);})));}
function bindP301(){if(view!=='p301')return;$('#p301-preview-all').onclick=()=>withButtonLock($('#p301-preview-all'),()=>p301PreviewDialog(),e=>toast(e.message,true));$('#p301-routes').onclick=()=>{view='assetHistory';page=1;historyPayload=null;historyError='';render();};selectionAdapters.set('p301:'+funding+':'+year,async ids=>{const records=registryRecords(state,year,funding).filter(r=>ids.includes(r.id)).map(r=>p301Record(state,r));if(records.some(r=>r.status!=='ready'||r.issues.length))throw Error('รายการที่เลือกมีข้อมูลไม่พร้อม กรุณาตรวจตั้งค่า พ.3-01 ก่อนส่งออก');await document.fonts.load('16px "TH SarabunPSK"');download(p301XlsxBlob(records,p301CurrentLayout()),'พ.3-01-ที่เลือก.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');});const safe=(button,fn)=>{button.onclick=()=>withButtonLock(button,fn,e=>operationFeedback('error',{title:'ดำเนินการไม่สำเร็จ',problem:e}));};$$('[data-p301-filter]').forEach(b=>b.onclick=()=>{p301Filter=b.dataset.p301Filter;page=1;render();});$('#p301-search').oninput=e=>{const pos=e.target.selectionStart;p301Query=e.target.value;page=1;render();$('#p301-search').focus();$('#p301-search').setSelectionRange(pos,pos);};$$('[data-p301-edit]').forEach(b=>safe(b,async()=>p301EditDialog(b.dataset.p301Edit)));$$('[data-p301-preview]').forEach(b=>safe(b,async()=>p301PreviewDialog(b.dataset.p301Preview)));$$('[data-p301-rule]').forEach(b=>safe(b,async()=>p301RuleDialog(b.dataset.p301Rule)));$$('[data-p301-export]').forEach(b=>safe(b,async()=>{const d=p301Record(state,findRegistryRecord(b.dataset.p301Export));if(d.issues.length)throw Error(d.issues.join(' · '));await document.fonts.load('16px "TH SarabunPSK"');download(p301XlsxBlob(d,p301CurrentLayout()),'พ.3-01-'+d.contractNo.replace(/[/\\]/g,'-')+'.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');}));safe($('#p301-defaults'),async()=>p301DefaultsDialog());safe($('#p301-year-export'),p301AllYearsPDF);}
function header(title,sub,actions=''){return `<div class="page-heading"><div><h1>${esc(title)}</h1><p class="page-description">${esc(sub)}</p></div><div class="actions">${actions}</div></div>`;}
function periodBar(showWeek=true){return `<div class="period-bar"><div class="period-control"><label class="field">กลุ่มงบ<select id="funding-select">${state.fundingSources.map(x=>`<option value="${x.id}" ${x.id===funding?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label class="field">ปีงบประมาณ<select id="year">${[...state.years].sort((a,b)=>b-a).map(y=>`<option value="${y}" ${y===year?'selected':''}>${y}</option>`).join('')}</select></label>${showWeek?`<label class="field week-control">สัปดาห์รายงาน<select id="report-select">${state.reports.filter(r=>reportMatchesScope(state,r,year,funding)).map(r=>`<option value="${r.id}" ${r.id===selected?'selected':''}>${esc(weekLabel(r)+' · '+(r.end?archiveDateRange(r.start,r.end):'ต้นฉบับ'))}</option>`).join('')}</select></label>`:''}</div>${showWeek?`<div class="sub"><span class="live-dot"></span>${report().locked?'รายงานเก็บประวัติแล้ว':'ฉบับร่าง · กำลังอัปเดต'}</div>`:''}</div>`;}
function stat(label,n,foot,icon,cls=''){return `<div class="stat ${cls}"><div class="stat-label">${label}</div><span class="stat-icon">${icon}</span><div class="stat-number">${n}<small>โครงการ</small></div><div class="stat-foot">${foot}</div></div>`;}
function miniSparklineSVG(values,stroke='#10b981',fill=null){if(!values||values.length<2)return '';const min=Math.min(...values),max=Math.max(...values),range=max-min||1;const pts=values.map((v,i)=>(i*(60/(values.length-1))).toFixed(1)+','+(20-((v-min)/range)*16+2).toFixed(1)).join(' ');const fillPath=fill?`<polygon fill="${fill}" points="0,24 ${pts} 60,24"/>`:'';return `<svg class="mini-sparkline" viewBox="0 0 60 24" aria-hidden="true">${fillPath}<polyline fill="none" stroke="${stroke}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" points="${pts}"/></svg>`;}
function deltaBadge(delta,invert=false){if(delta===0)return '<span class="delta-badge neutral">0</span>';const isPos=delta>0;const cls=(isPos!==invert)?'pos':'neg';const sign=isPos?'+':'';return `<span class="delta-badge ${cls}">${sign}${delta.toFixed(delta%1===0?0:1)}</span>`;}
function ovSpark(values,color){const v=(values||[]).map(Number).filter(Number.isFinite),a=v.length>1?v:[v[0]??0,v[0]??0],min=Math.min(...a),max=Math.max(...a),range=max-min||1,w=120,h=36,line=a.map((n,i)=>(i*w/(a.length-1)).toFixed(1)+','+(h-4-((n-min)/range)*(h-10)).toFixed(1)).join(' ');return `<svg class="ov-spark" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" aria-hidden="true"><polygon points="0,${h} ${line} ${w},${h}" fill="${color}" opacity=".12"/><polyline points="${line}" fill="none" stroke="${color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/></svg>`;}
function ovBadge(delta,invert=false){const d=Math.round(delta*10)/10;if(!d)return '<span class="ov-badge">0</span>';return `<span class="ov-badge ${(d>0)!==invert?'pos':'neg'}">${d>0?'+':''}${d}</span>`;}
function ovMillions(v){return (v/1e6).toLocaleString('th-TH',{minimumFractionDigits:v?2:0,maximumFractionDigits:2})+' ลบ.';}
function ovPercent(n,total){return total?(n/total*100).toFixed(1).replace(/\.0$/,''):'0';}
const OV_COLORS=['var(--sidebar)','var(--green)','var(--gold)','#a9b8b0','var(--payment-ink)','var(--orange)'];
let dashboardRoute='',dashboardSupervisor='',dashboardStage='all',dashboardPendingPage=1,dashboardPendingQuery='',dashboardPendingMode='all',dashboardToolsOpen=false;

/** Render a precomputed exclusive status model. Escapes all labels; no state writes. */
function renderContractStatusSection(distribution){return `<section class="card dash-v25-card pipe dash-pipeline-card"><div class="dash-pipeline-header"><h2>สถานะสัญญา</h2><span>สัดส่วนสถานะสัญญา ${distribution.some(x=>x.count)?'100':'0'}%</span></div><div class="pipeline-bar-track">${distribution.map(x=>`<button type="button" class="bar-seg ${x.key}" data-dashboard-status="${x.key}" style="width:${x.percent}%;background:${x.color}" aria-label="${esc(x.label)}: ${x.count} สัญญา (${x.percent.toFixed(2)}%)" title="${esc(x.label)}: ${x.count} สัญญา (${x.percent.toFixed(2)}%)"></button>`).join('')}</div><div class="pipeline-stages">${distribution.map(x=>`<button type="button" class="pipeline-stage ${x.key}" data-dashboard-status="${x.key}"><span class="stage-label">${esc(x.label)}</span><span class="stage-val"><strong style="color:#172b24!important">${x.count}</strong> สัญญา</span><span class="stage-badge">${x.percent.toFixed(2)}%</span><span class="stage-mini-track"><span style="display:block;height:100%;width:${x.percent}%;background:${x.color}"></span></span></button>`).join('')}</div></section>`;}
/** Render pending projections; paginated by the shared read-table owner. No writes. */
function renderPendingActionsTable(rows,printing=false){const size=printing?Math.max(1,rows.length):DASHBOARD_VIEW_CONFIG.pendingPageSize,pages=Math.max(1,Math.ceil(rows.length/size)),current=printing?1:Math.min(dashboardPendingPage,pages);rows=sortTableRecords(rows,'pending',x=>[x.p.contract,x.p.title,x.stage,x.diffPct,x.remainingDays]);const total=rows.length;rows=rows.slice((current-1)*size,current*size);return `<section class="card dash-pending"><h2>งานค้างดำเนินการ <span class="pill">${total}</span></h2><p class="sub">รวมงานยังไม่แล้วเสร็จ รอส่งมอบ และรอเบิกจ่าย · เรียงตามความเร่งด่วน</p><div class="table-scroll"><table class="tbl dash-v25-clean-table" data-table-owner="pending"><thead><tr><th>เลขสัญญา</th><th>โครงการ</th><th>สถานะ</th><th>ผลต่างแผน/ผล</th><th>วันคงเหลือ</th><th>ดำเนินการ</th></tr></thead><tbody>${rows.map(({p,e,stage,diffPct,remainingDays})=>`<tr><td>${esc(p.contract)}</td><td>${esc(p.title)}</td><td>${esc(DASHBOARD_STAGES.find(x=>x.key===stage)?.label)}</td><td>${diffPct.toFixed(2)}%</td><td>${remainingDays===null?'ยังไม่ระบุ':remainingDays}</td><td><button type="button" class="btn" data-edit="${esc(p.id)}">ดูรายละเอียด</button></td></tr>`).join('')||'<tr><td colspan="6">ไม่มีงานค้างดำเนินการตามตัวกรอง</td></tr>'}</tbody></table></div><div class="table-foot"><span>หน้า ${current} / ${pages}</span><div class="actions"><button type="button" class="btn" data-pending-page="${current-1}" ${current<=1?'disabled':''}>ก่อนหน้า</button><button type="button" class="btn" data-pending-page="${current+1}" ${current>=pages?'disabled':''}>ถัดไป</button></div></div></section>`;}
/** @param {Array} rows Filtered rows. @returns {string} Escaped, bounded main table. No state writes. */
function renderDashboardProjectsTable(rows){
 rows=sortTableRecords(rows,'projects',x=>[x.p.contract,x.p.title,x.record?.contractValue,x.e.actual,x.stage?.key]);
 const size=DASHBOARD_VIEW_CONFIG.recentPageSize,pages=Math.max(1,Math.ceil(rows.length/size)),current=Math.min(page,pages);
 return `<section class="card table-card"><div class="table-top"><h2>ตารางโครงการทั้งหมด</h2><span>${rows.length} สัญญา</span></div><div class="table-scroll"><table class="tbl dash-v25-clean-table" data-table-owner="projects" data-selection-key="weekly:${selected}" data-selection-ids="${esc(JSON.stringify(rows.map(x=>x.p.id)))}"><thead><tr><th>เลขสัญญา / สายทาง</th><th>โครงการ / ผู้รับจ้าง</th><th>ความก้าวหน้า</th><th>สถานะ / รายละเอียด</th></tr></thead><tbody>${rows.slice((current-1)*size,current*size).map(({p,e,record:r,stage,actualPct})=>`<tr data-id="${esc(p.id)}"><td>${esc(p.contract)}<div class="sub">${(r.segments||[]).map(segment=>esc(['ทล. '+segment.routeNumber,segment.controlSection].filter(Boolean).join(' / '))).join('<br>')}</div></td><td>${esc(p.title)}<div class="sub">${esc(p.contractor)} · ${r.contractValue==null||r.contractValue===''?'ยังไม่ระบุวงเงิน':money(r.contractValue)}</div></td><td><div class="dash-table-progress"><span style="width:${actualPct}%"></span></div><strong>${Number(e.actual).toFixed(1)}%</strong><div class="sub">แผน ${Number(e.plan).toFixed(1)}%</div></td><td><span class="pill">${esc(stage?.label||'ยังไม่ระบุ')}</span><button class="btn" data-edit="${esc(p.id)}">ดูรายละเอียด</button></td></tr>`).join('')||'<tr><td colspan="4">ไม่พบโครงการตามตัวกรอง</td></tr>'}</tbody></table></div><div class="table-foot"><span>หน้า ${current} / ${pages}</span><div class="actions"><button type="button" class="btn" data-page="${current-1}" ${current<=1?'disabled':''}>ก่อนหน้า</button><button type="button" class="btn" data-page="${current+1}" ${current>=pages?'disabled':''}>ถัดไป</button></div></div></section>`;
}
