function segmentsEditorHTML(r){return `<datalist id="road-record-options">${(state.settings.roadSections||[]).map(x=>`<option value="${esc([x.routeNumber,x.controlSection,x.sectionName].join(' · '))}">`).join('')}</datalist><div class="registry-section route-editor">${['routeNumber','controlSection','sectionName'].map(k=>`<datalist id="road-list-${k}">${[...new Set((state.settings.roadSections||[]).map(r=>r[k]).filter(Boolean))].map(v=>`<option value="${esc(v)}">`).join('')}</datalist>`).join('')}<div class="table-scroll"><table class="segment-edit-table"><caption>ช่วงทางของสัญญา — กดแก้ไขที่สายที่ต้องการ</caption><thead><tr><th>สาย / ช่วง</th>${segmentFields.slice(0,6).map(([,label])=>`<th scope="col">${label}</th>`).join('')}<th>จัดการ</th></tr></thead><tbody id="segment-rows">${(r.segments||[]).map((seg,i)=>segmentRowHTML(seg,i)).join('')}</tbody></table></div><p class="hint" data-segments-empty ${(r.segments||[]).length?'hidden':''}>ยังไม่มีช่วงทาง เพิ่มสาย / ช่วงทางได้โดยไม่ต้องสร้างสัญญาใหม่</p><button type="button" class="btn" id="add-registry-segment">+ เพิ่มสาย / ช่วงทาง</button><p class="hint">กรอกหลายสายภายใต้ ID Code เดียวกัน แล้วกดบันทึกสัญญาเพื่อบันทึกทั้งหมด</p><p class="hint" role="status" id="segment-status"></p></div>`;}
function bindSegmentEditor(){const container=$('#segment-rows');if(!container)return;bindClearSearches(container);const rows=()=>[...container.querySelectorAll('[data-segment-index]')],editorFor=row=>container.querySelector('[data-segment-editor-for="'+row.dataset.segmentIndex+'"]'),renumber=()=>{rows().forEach((row,i)=>{row.querySelector('[data-segment-number]').textContent='สาย / ช่วงที่ '+(i+1);row.querySelector('[data-edit-segment]').setAttribute('aria-label','แก้ไขสาย / ช่วงที่ '+(i+1));row.querySelector('[data-remove-segment]').setAttribute('aria-label','นำสาย / ช่วงที่ '+(i+1)+' ออก');});$('[data-segments-empty]').hidden=rows().length>0;},refresh=row=>{const editor=editorFor(row);for(const [key]of segmentFields.slice(0,6))row.querySelector('[data-segment-value="'+key+'"]').textContent=editor.querySelector('[name="seg_'+row.dataset.segmentIndex+'_'+key+'"]').value.trim()||'ยังไม่ระบุ';};container.addEventListener('input',e=>{const editor=e.target.closest('[data-segment-editor-for]');if(editor){if(e.target.hasAttribute('data-road-picker')){const road=state.settings.roadSections.find(x=>[x.routeNumber,x.controlSection,x.sectionName].join(' · ')===e.target.value);if(road)for(const k of ['routeNumber','controlSection','sectionName'])editor.querySelector('[name$=_'+k+']').value=road[k];}refresh(container.querySelector('[data-segment-index="'+editor.dataset.segmentEditorFor+'"]'));}});container.onclick=e=>{const button=e.target.closest('button');if(!button)return;const owner=button.closest('[data-segment-index],[data-segment-editor-for]'),index=owner?.dataset.segmentIndex??owner?.dataset.segmentEditorFor,row=container.querySelector('[data-segment-index="'+index+'"]');if(!row)return;const editor=editorFor(row),confirm=editor.querySelector('.segment-remove-confirm');if(button.hasAttribute('data-edit-segment')){editor.hidden=false;button.setAttribute('aria-expanded','true');editor.querySelector('input').focus();}if(button.hasAttribute('data-finish-segment')){refresh(row);editor.hidden=true;row.querySelector('[data-edit-segment]').setAttribute('aria-expanded','false');row.querySelector('[data-edit-segment]').focus();}if(button.hasAttribute('data-remove-segment')){editor.hidden=false;row.querySelector('[data-edit-segment]').setAttribute('aria-expanded','true');confirm.hidden=false;confirm.querySelector('[data-cancel-remove-segment]').focus();}if(button.hasAttribute('data-cancel-remove-segment')){confirm.hidden=true;row.querySelector('[data-remove-segment]').focus();}if(button.hasAttribute('data-confirm-remove-segment')){row.remove();editor.remove();renumber();$('#segment-status').textContent='นำช่วงทางออกจากรายการแก้ไขแล้ว ยังไม่ได้บันทึก';$('#add-registry-segment').focus();}};$('#add-registry-segment').onclick=()=>{const index=Math.max(-1,...rows().map(row=>+row.dataset.segmentIndex))+1;container.insertAdjacentHTML('beforeend',segmentRowHTML({},index,true));bindClearSearches(container);renumber();$('#segment-status').textContent='เพิ่มช่องกรอกช่วงทางแล้ว ยังไม่ได้บันทึก';container.lastElementChild.querySelector('input').focus();};renumber();}
function readSegmentForm(f,r){return segmentsFromForm(f);}

function personnelRowHTML(member,group,index,open=false){const token=group+'_'+index,ordinal=member.ordinal||index+1;return `<tr data-person-row="${token}"><th scope="row" data-person-ordinal>${ordinal}</th><td data-person-name>${esc(member.name||'ยังไม่ระบุ')}</td><td data-person-position>${esc(member.position||'ยังไม่ระบุ')}</td><td data-person-duty>${esc(member.duty||personnelDuty(group,ordinal))}</td><td><div class="row-actions"><button type="button" class="btn" data-edit-person aria-expanded="${open}" aria-controls="person-editor-${token}">แก้ไข</button><button type="button" class="btn danger" data-remove-person>ลบ</button></div></td></tr><tr id="person-editor-${token}" data-person-editor="${token}" ${open?'':'hidden'}><td colspan="5"><div class="segment-fields"><div class="form-grid">${selectField('ประเภทบุคลากร','person_'+token+'_group',[{value:'inspection',label:'คณะกรรมการตรวจรับพัสดุ'},{value:'supervision',label:'ผู้ควบคุมงาน'}],group)}${field('ลำดับ','person_'+token+'_ordinal',ordinal,'number','required min="1" step="1"')}${field('ชื่อ–สกุล','person_'+token+'_name',member.name||'','text','required list="personnel-full-names"')}${field('ตำแหน่ง','person_'+token+'_position',member.position||'')}${selectField('บทบาท','person_'+token+'_duty',group==='inspection'?['ประธาน','กรรมการ']:['ผู้ควบคุมงาน','ผู้ช่วยผู้ควบคุมงาน'],member.duty||personnelDuty(group,ordinal))}</div><button type="button" class="btn" data-finish-person>เสร็จสิ้นการกรอกบุคลากร</button><p class="form-error" role="alert"></p><div class="person-remove-confirm" hidden><p>ลบรายชื่อออกจากสัญญานี้หรือไม่? ไม่ลบบุคคลจากข้อมูลพื้นฐาน และจะบันทึกเมื่อกดบันทึกสัญญา</p><button type="button" class="btn danger" data-confirm-remove-person>ยืนยันลบจากสัญญา</button><button type="button" class="btn" data-cancel-remove-person>เก็บรายชื่อไว้</button></div></div></td></tr>`;}
function personnelEditorHTML(r){return `<div class="personnel-editor"><datalist id="personnel-full-names">${state.supervisors.map(p=>`<option value="${esc(p.name)}">`).join('')}</datalist>${[['inspection','คณะกรรมการตรวจรับพัสดุ'],['supervision','ผู้ควบคุมงาน']].map(([group,label])=>`<section class="registry-section"><h4>${label}</h4><div class="table-scroll"><table class="personnel-edit-table"><thead><tr><th>ลำดับ</th><th>ชื่อ–สกุล</th><th>ตำแหน่ง</th><th>บทบาท</th><th>จัดการ</th></tr></thead><tbody data-person-group="${group}">${assignmentDetails(state,r,group).map((m,i)=>personnelRowHTML(m,group,i)).join('')}</tbody></table></div><button type="button" class="btn" data-add-person="${group}">+ เพิ่ม${label}</button></section>`).join('')}<p class="hint">ชื่อใช้ทะเบียนบุคลากรร่วมกัน ตำแหน่ง ลำดับ และบทบาทเก็บเฉพาะสัญญานี้</p><p class="hint" role="status" id="personnel-editor-status"></p></div>`;}
function bindPersonnelEditor(){const root=$('.personnel-editor');if(!root)return;const locate=token=>({row:root.querySelector('[data-person-row="'+token+'"]'),editor:root.querySelector('[data-person-editor="'+token+'"]')}),input=(e,key)=>e.querySelector('[name$=_'+key+']'),summary=token=>{const {row,editor}=locate(token);for(const key of ['ordinal','name','position','duty'])row.querySelector('[data-person-'+key+']').textContent=input(editor,key).value||'ยังไม่ระบุ';};root.oninput=e=>{const editor=e.target.closest('[data-person-editor]');if(editor){if(e.target.name.endsWith('_name')){const p=state.supervisors.find(p=>p.name===e.target.value.trim());if(p?.position&&!input(editor,'position').value.trim())input(editor,'position').value=p.position;}summary(editor.dataset.personEditor);}};root.onchange=e=>{const editor=e.target.closest('[data-person-editor]');if(!editor)return;if(e.target.name.endsWith('_name')){const p=state.supervisors.find(p=>p.name===e.target.value.trim());if(p?.position&&!input(editor,'position').value.trim())input(editor,'position').value=p.position;}if(e.target.name.endsWith('_group')){const group=e.target.value,ordinal=root.querySelector('[data-person-group="'+group+'"]').querySelectorAll('[data-person-row]').length+1;input(editor,'ordinal').value=ordinal;input(editor,'duty').innerHTML=(group==='inspection'?['ประธาน','กรรมการ']:['ผู้ควบคุมงาน','ผู้ช่วยผู้ควบคุมงาน']).map(x=>`<option>${x}</option>`).join('');input(editor,'duty').value=personnelDuty(group,ordinal);}summary(editor.dataset.personEditor);};root.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.addPerson){const group=b.dataset.addPerson,tbody=root.querySelector('[data-person-group="'+group+'"]'),index=Math.max(-1,...[...root.querySelectorAll('[data-person-row]')].map(x=>+x.dataset.personRow.split('_').at(-1)))+1,ordinal=tbody.querySelectorAll('[data-person-row]').length+1;tbody.insertAdjacentHTML('beforeend',personnelRowHTML({ordinal},group,index,true));bindClearSearches(tbody);tbody.lastElementChild.querySelector('[name$=_name]').focus();$('#personnel-editor-status').textContent='เพิ่มช่องกรอกแล้ว ยังไม่ได้บันทึก';return;}const owner=b.closest('[data-person-row],[data-person-editor]'),token=owner?.dataset.personRow||owner?.dataset.personEditor;if(!token)return;const {row,editor}=locate(token),confirm=editor.querySelector('.person-remove-confirm');if(b.hasAttribute('data-edit-person')){editor.hidden=false;b.setAttribute('aria-expanded','true');input(editor,'name').focus();}if(b.hasAttribute('data-finish-person')){if(!input(editor,'name').value.trim()){editor.querySelector('.form-error').textContent='กรุณาระบุชื่อ–สกุล';input(editor,'name').focus();return;}summary(token);const target=root.querySelector('[data-person-group="'+input(editor,'group').value+'"]');if(row.parentNode!==target){target.append(row,editor);}editor.hidden=true;row.querySelector('[data-edit-person]').setAttribute('aria-expanded','false');row.querySelector('[data-edit-person]').focus();}if(b.hasAttribute('data-remove-person')){editor.hidden=false;row.querySelector('[data-edit-person]').setAttribute('aria-expanded','true');confirm.hidden=false;confirm.querySelector('[data-cancel-remove-person]').focus();}if(b.hasAttribute('data-cancel-remove-person')){confirm.hidden=true;row.querySelector('[data-remove-person]').focus();}if(b.hasAttribute('data-confirm-remove-person')){const group=row.parentNode.dataset.personGroup;row.remove();editor.remove();const tbody=root.querySelector('[data-person-group="'+group+'"]');[...tbody.querySelectorAll('[data-person-row]')].forEach((r,i)=>{const e=locate(r.dataset.personRow).editor;input(e,'ordinal').value=i+1;input(e,'duty').value=personnelDuty(group,i+1);summary(r.dataset.personRow);});root.querySelector('[data-add-person="'+group+'"]').focus();$('#personnel-editor-status').textContent='นำรายชื่อออกจากรายการแก้ไขแล้ว ยังไม่ได้บันทึก';}};}

function personnelImportDialog(){let records=[],preview=[],sourceName='';modal('นำเข้าคณะกรรมการตรวจรับพัสดุและผู้ควบคุมงาน · ก-4',`<form id="personnel-import"><p class="hint">อ่านเฉพาะรายชื่อคณะกรรมการตรวจรับพัสดุและผู้ควบคุมงาน จับคู่ ID Code ในปีและกลุ่มงบที่เลือก ไม่ทับรหัสงานหรือข้อมูลสัญญาจาก ก-3 แยกชื่อ ตำแหน่งในวงเล็บ และลำดับ กำหนดประธาน/กรรมการและผู้ควบคุม/ผู้ช่วยตามลำดับ ชื่อเดิมใช้คีย์เดิม</p><div class="form-grid">${selectField('กลุ่มงบ','funding',state.fundingSources.map(x=>({value:x.id,label:x.name})),funding)}${selectField('ปีงบประมาณ','year',[...state.years].sort((a,b)=>b-a),year)}<label class="field wide">ไฟล์ ก-4 (.xlsx)<input id="personnel-file" type="file" accept=".xlsx" required></label></div><button class="btn primary" id="read-personnel" type="button">อ่านและตรวจรายชื่อ</button><div id="personnel-preview"></div><p class="form-error" role="alert"></p></form>`);const form=$('#personnel-import');$('#read-personnel').onclick=async()=>{const b=$('#read-personnel');b.disabled=true;try{const file=$('#personnel-file').files[0];if(!file)throw Error('เลือกไฟล์ ก-4 ก่อน');records=(await readG3Workbook(await file.arrayBuffer(),'personnel')).records;sourceName=file.name;if(await ensureImportScope(form))show();}catch(e){showFormError(form,e.message);}finally{b.disabled=false;}};const show=()=>{preview=previewPersonnelImport(state,records,+form.elements.year.value,form.elements.funding.value);$('#personnel-preview').innerHTML=`<div class="notice">อ่าน ${preview.length} โครงการ · มีปัญหา ${preview.filter(x=>x.errors.length).length} · เปลี่ยน ${preview.filter(x=>x.changes.length&&!x.errors.length).length}</div><div class="table-scroll"><table data-selection-key="import-personnel" data-selection-ids="${esc(JSON.stringify(preview.map(x=>String(x.index))))}"><thead><tr><th>ID Code / สัญญา</th><th>คณะกรรมการตรวจรับพัสดุ</th><th>ผู้ควบคุมงาน</th><th>ผลตรวจ</th></tr></thead><tbody>${preview.map(x=>`<tr data-select-id="${x.index}"><td>${esc(x.record.sourceId)}<br>${esc(x.record.contract)}</td><td>${x.record.committeeMembers.map(a=>esc(a.ordinal+'. '+a.name+' · '+(a.position||'ยังไม่ระบุตำแหน่ง')+' · '+a.duty)).join('<br>')}</td><td>${x.record.supervisorMembers.map(a=>esc(a.ordinal+'. '+a.name+' · '+(a.position||'ยังไม่ระบุตำแหน่ง')+' · '+a.duty)).join('<br>')}</td><td>${esc(x.errors.join(' · ')||(!x.changes.length?'เหมือนเดิม · ไม่เขียนซ้ำ':'พร้อมอัปเดต'))}${!x.errors.length?csvChangeHTML(x.changes,state):''}</td></tr>`).join('')}</tbody></table></div><div class="dialog-actions"><button type="button" class="btn primary" id="commit-personnel">นำเข้ารายชื่อและเชื่อมสัญญา</button></div>`;tableSelections.delete('import-personnel');mountSelections();$('#personnel-preview [data-selection-export]')?.remove();$('#commit-personnel').onclick=()=>commitCSVForm($('#commit-personnel'),async()=>{const chosen=selectionFor('import-personnel',preview.map(x=>String(x.index)));let result;await mutate('นำเข้าคณะกรรมการและผู้ควบคุมงาน',s=>{const before=cloneForMutation(s);result=applyPersonnelImport(s,preview,chosen);Object.assign(s,result.state);if(result.updated)captureImportResult(s,'contractRegistry',before,sourceName);},{format:'XLSX',fileName:sourceName});$('#modal').close();render();toast(`เชื่อม ${result.updated} สัญญา · บุคคลใหม่ ${result.created} · เติมตำแหน่ง ${result.updatedPeople||0} · เหมือนเดิม ${result.unchanged}`);},e=>showFormError(form,e.message));};form.elements.year.onchange=form.elements.funding.onchange=async()=>{try{if(await ensureImportScope(form)&&records.length)show();}catch(e){showFormError(form,e.message);}};$('#personnel-file').onchange=()=>{records=[];preview=[];$('#personnel-preview').innerHTML='';};}

function roadLibraryDialog(query='',page=1){const roads=state.settings.roadSections||[],filtered=roads.filter(r=>[r.routeNumber,r.controlSection,r.sectionName].join(' ').toLowerCase().includes(query.toLowerCase())),pages=Math.max(1,Math.ceil(filtered.length/25));page=Math.min(page,pages);modal('ข้อมูลพื้นฐาน · ทางหลวงและตอนควบคุม',`<p class="hint">เพิ่มอัตโนมัติจากช่วงทางที่นำเข้าและบันทึก กม.และทิศทางเก็บแยกตามสัญญา การแก้ข้อมูลกลางไม่เปลี่ยนสัญญาเก่า</p><label class="field">ค้นหาทางหลวง / ตอนควบคุม<input id="road-master-search" value="${esc(query)}"></label><div class="actions"><button type="button" class="btn primary" id="new-road-master">+ เพิ่มตอนทางหลวง</button><button type="button" class="btn" id="export-road-master">ส่งออก CSV</button></div><div class="table-scroll"><table><thead><tr><th>ทางหลวง</th><th>ตอนควบคุม</th><th>ชื่อตอน / โครงการ</th><th>จัดการ</th></tr></thead><tbody>${filtered.slice((page-1)*25,page*25).map(r=>`<tr><td>${esc(r.routeNumber)}</td><td>${esc(r.controlSection)}</td><td>${esc(r.sectionName)}</td><td><div class="row-actions"><button type="button" class="btn" data-edit-road-master="${esc(r.id)}">แก้ไข</button><button type="button" class="btn danger" data-delete-road-master="${esc(r.id)}">ลบ</button></div></td></tr>`).join('')||'<tr><td colspan="4">ยังไม่มีข้อมูล เพิ่มอัตโนมัติเมื่อนำเข้า ก-3 หรือเพิ่มช่วงทาง</td></tr>'}</tbody></table></div><div class="table-foot"><span>${filtered.length} รายการ · หน้า ${page} / ${pages}</span><div class="actions"><button type="button" class="btn" id="road-master-prev" ${page<=1?'disabled':''}>ก่อนหน้า</button><button type="button" class="btn" id="road-master-next" ${page>=pages?'disabled':''}>ถัดไป</button></div></div>`);$('#road-master-prev').onclick=()=>roadLibraryDialog(query,page-1);$('#road-master-next').onclick=()=>roadLibraryDialog(query,page+1);$('#road-master-search').oninput=e=>{const value=e.target.value,pos=e.target.selectionStart;roadLibraryDialog(value,1);$('#road-master-search').focus();$('#road-master-search').setSelectionRange(pos,pos);};$('#new-road-master').onclick=()=>roadMasterEdit();$('#export-road-master').onclick=()=>{const q=v=>'"'+String(v||'').replace(/"/g,'""')+'"';download('\ufeff'+[['หมายเลขทางหลวง','ตอนควบคุม','ชื่อตอน/โครงการ'],...filtered.map(r=>[r.routeNumber,r.controlSection,r.sectionName])].map(r=>r.map(q).join(',')).join('\r\n'),'ทางหลวงและตอนควบคุม.csv','text/csv;charset=utf-8');};$$('[data-edit-road-master]').forEach(b=>b.onclick=()=>roadMasterEdit(b.dataset.editRoadMaster));$$('[data-delete-road-master]').forEach(b=>b.onclick=()=>{const item=roads.find(r=>r.id===b.dataset.deleteRoadMaster),used=state.contractRegistry.some(r=>r.segments?.some(seg=>['routeNumber','controlSection','sectionName'].every(k=>(seg[k]||'')===(item[k]||''))));if(used)return toast('ตอนทางหลวงนี้ยังใช้ในสัญญา ไม่สามารถลบได้',true);confirmAction('ลบตอนทางหลวง '+item.routeNumber+' '+item.controlSection,'ลบเฉพาะข้อมูลพื้นฐานรายการที่ไม่ถูกใช้งาน',()=>mutate('ลบตอนทางหลวง',s=>{s.settings.roadSections=s.settings.roadSections.filter(r=>r.id!==item.id);}));});}
function roadMasterEdit(id){const existing=state.settings.roadSections?.find(r=>r.id===id)||{};modal(id?'แก้ไขตอนทางหลวง':'เพิ่มตอนทางหลวง',`<form novalidate><div class="form-grid">${field('หมายเลขทางหลวง','routeNumber',existing.routeNumber||'','text','required')}${field('ตอนควบคุม','controlSection',existing.controlSection||'')}${field('ชื่อตอน / โครงการ','sectionName',existing.sectionName||'')}</div>${buttons('บันทึกตอนทางหลวง')}</form>`,f=>mutate('บันทึกข้อมูลพื้นฐานทางหลวง',s=>{const record={id:id||'ROAD-'+uid(),...Object.fromEntries(['routeNumber','controlSection','sectionName'].map(k=>[k,String(f.get(k)||'').trim()]))};s.settings.roadSections||=[];if(s.settings.roadSections.some(r=>r.id!==id&&['routeNumber','controlSection','sectionName'].every(k=>r[k]===record[k])))throw Error('มีตอนทางหลวงนี้อยู่แล้ว');const index=s.settings.roadSections.findIndex(r=>r.id===id);if(index>=0)s.settings.roadSections[index]=record;else s.settings.roadSections.push(record);}));}
function personnelLibraryDialog(role='inspection'){const people=state.supervisors.filter(x=>x.personRoles?.includes(role));modal(role==='inspection'?'ข้อมูลพื้นฐาน · คณะกรรมการตรวจรับพัสดุ':'ข้อมูลพื้นฐาน · ผู้ควบคุมงาน',`<p class="hint">ชื่อเต็มใช้เชื่อมหลายสัญญา โดยไม่สร้างบุคคลซ้ำ</p><button class="btn" type="button" id="export-personnel-library">ส่งออกรายชื่อ CSV</button><div class="table-scroll"><table><thead><tr><th>ชื่อบุคคล</th><th>ตำแหน่งปัจจุบัน</th><th>สัญญาที่เกี่ยวข้อง</th><th>จัดการ</th></tr></thead><tbody>${people.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.position||'ยังไม่ระบุ')}</td><td>${state.contractRegistry.filter(r=>(role==='inspection'?r.committeeIds:r.supervisorIds)?.includes(p.id)).length}</td><td><button class="btn" type="button" data-edit-library-person="${esc(p.id)}">แก้ไข</button></td></tr>`).join('')||'<tr><td colspan="2">ยังไม่มีรายชื่อ นำเข้าแบบ ก-4 เพื่อเพิ่มได้</td></tr>'}</tbody></table></div>`);$$('[data-edit-library-person]').forEach(b=>b.onclick=()=>{const person=state.supervisors.find(p=>p.id===b.dataset.editLibraryPerson);modal('แก้ไขข้อมูลบุคลากร',`<form>${field('ชื่อ–สกุล','name',person.name,'text','required')}${field('ตำแหน่งปัจจุบัน','position',person.position||'')}${buttons()}</form>`,f=>mutate('แก้ไขบุคลากร',s=>{const p=s.supervisors.find(p=>p.id===person.id),name=String(f.get('name')).trim();if(s.supervisors.some(x=>x.id!==p.id&&x.name===name))throw Error('ชื่อซ้ำ');p.name=name;p.position=String(f.get('position')||'').trim();updateMasterReferences(s,'supervisors',p);}));});$('#export-personnel-library').onclick=()=>{download(masterCSV({...state,supervisors:people},'supervisors'),'คณะกรรมการตรวจรับพัสดุ.csv','text/csv;charset=utf-8');void logActivity('ส่งออกรายชื่อคณะกรรมการ CSV',[],{count:people.length});};}
function registryColumnValue(r,key){const current=registryCurrent(state,r),segments=r.segments||[];switch(key){case'sourceId':return r.sourceId||'';case'contract':return r.contract||'';case'title':return[r.workCode,r.title].filter(Boolean).join(' ');case'workType':return state.workTypes.find(x=>x.id===r.workTypeId)?.name||'';case'budgetAccount':return r.budgetAccount||'';case'contractValue':return Number(r.contractValue)||0;case'actualCost':return r.actualCost===''||r.actualCost==null?'':Number(r.actualCost);case'contractorName':return r.contractorName||r.contractorRaw||'';case'highway':return segments.map(x=>[x.highway||x.roadNo,x.controlSection||x.control].filter(Boolean).join(' / ')).join('\n');case'committee':return assignmentDetails(state,r,'inspection').map(x=>x.name+(x.duty?' ('+x.duty+')':'')).join('\n');case'supervisor':return assignmentDetails(state,r,'supervision').map(x=>x.name+(x.duty?' ('+x.duty+')':'')).join('\n');case'progress':return Number(current.currentActual)||0;case'handover':return[r.deliveryDate?`ส่งมอบ ${fmt(r.deliveryDate)}`:'',r.acceptanceDate?`ตรวจรับ ${fmt(r.acceptanceDate)}`:''].filter(Boolean).join(' · ');case'payment':return r.finalPaymentDate?`เบิกจ่ายแล้ว ${fmt(r.finalPaymentDate)}`:current.payment||r.payment||'ยังไม่ระบุ';case'duration':return[r.start&&r.end?`${fmt(r.start)} – ${fmt(effectiveEnd(r))}`:'',r.duration?`${r.duration} วัน`:''].filter(Boolean).join(' · ');case'details':return[r.quantity!==''&&r.quantity!=null?`${r.quantity} ${r.unit||''}`.trim():'',r.note||r.notes||''].filter(Boolean).join(' · ');default:return'';}}
function registryColumnCell(r,key){const value=registryColumnValue(r,key);if(key==='sourceId')return `<td class="source-code">${esc(value||'–')}</td>`;if(key==='contract')return `<td><strong>${esc(r.contract)}</strong><div>${dataChangeBadge(r)}${registryExpired(state,r)?'<span class="pill warn">หมดอายุสัญญาแล้ว</span>':''}</div></td>`;if(key==='title')return `<td class="registry-job"><strong><span class="work-code">${esc(r.workCode||'–')}</span> ${esc(r.title)}</strong>${latestContractEntry(state,r)?.entry?`<div class="progress registry-latest-progress" aria-label="ผลงานล่าสุด"><div class="track"><span style="width:${Math.max(0,Math.min(100,Number(registryCurrent(state,r).currentActual)||0))}%"></span></div><small>ผลงานล่าสุด ${Number(registryCurrent(state,r).currentActual||0).toFixed(2)}%</small></div>`:'<small class="sub">ยังไม่มีข้อมูลผลงาน</small>'}</td>`;if(['contractValue','actualCost'].includes(key))return `<td class="num">${value===''?'ยังไม่ระบุ':Number(value).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2})}</td>`;if(key==='progress')return `<td><div class="progress"><div class="track"><span style="width:${Math.max(0,Math.min(100,Number(value)||0))}%"></span></div>${Number(value||0).toFixed(2)}%</div></td>`;if(['committee','supervisor'].includes(key))return `<td>${String(value).split('\n').filter(Boolean).map(x=>`<div class="registry-person">${esc(x)}</div>`).join('')||'–'}</td>`;return `<td>${esc(value||'–')}</td>`;}
function registryTable(all){all||=registryVisibleRecords();const rows=all.filter(r=>advancedFilterMatch({r})&&(!registryFilter||(registryFilter==='unmatched'?(r.contractorNeedsReview||!r.contractorId):registryFilter==='expired'?registryExpired(state,r):registryFilter==='ongoing'?(!r.finalPaymentDate&&!r.acceptanceDate&&r.payment!=='เบิกจ่ายแล้ว'):registryFilter==='pay'?(Boolean(r.acceptanceDate)&&!r.finalPaymentDate&&r.payment!=='เบิกจ่ายแล้ว'):registryFilter==='paid'?(Boolean(r.finalPaymentDate)||r.payment==='เบิกจ่ายแล้ว'):true))&&(!budgetFilter||(r.budgetAccount||'ยังไม่ระบุ')===budgetFilter)&&(!query||[r.sourceId,r.contract,r.title,r.workCode,r.budgetAccount,r.contractorRaw,r.contractorName,...personnelNames(state,r)].join(' ').toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>compareTableValues(registryColumnValue(a,registrySort.key),registryColumnValue(b,registrySort.key))*registrySort.dir);const size=tableSize('registry'),pages=Math.max(1,Math.ceil(rows.length/size));page=Math.min(page,pages);return `<div class="card registry-panel"><div class="table-scroll"><table class="registry-table" data-table-owner="registry" data-column-values="${esc(JSON.stringify(rows.map(r=>registryColumnDefinitions.map(([key])=>registryColumnValue(r,key)))))}" data-selection-key="registry:${funding}:${year}" data-selection-ids="${esc(JSON.stringify(rows.map(x=>x.id)))}"><thead><tr>${registryColumnDefinitions.map(([key,label])=>sortHead(label,key,'registry',registrySort)).join('')}<th>จัดการ</th></tr></thead><tbody>${rows.slice((page-1)*size,page*size).map(r=>`<tr data-registry-row="${r.id}" tabindex="0" aria-label="ดูสัญญา ${esc(r.contract)}">${registryColumnDefinitions.map(([key])=>registryColumnCell(r,key)).join('')}<td><div class="row-actions">${iconButton('view','ดูสัญญา',`data-registry-view="${r.id}"`)}${iconButton('edit','แก้ไขสัญญา',`data-registry-edit="${r.id}"`)}${iconButton('delete','ลบสัญญา',`data-registry-delete="${r.id}"`)}</div></td></tr>`).join('')||`<tr><td colspan="${registryColumnDefinitions.length+1}" class="empty">ไม่มีสัญญาตามตัวกรองนี้</td></tr>`}</tbody></table></div><div class="table-foot"><span>หน้า ${page} / ${pages}</span><div class="actions"><button class="btn" data-registry-page="${page-1}" ${page<=1?'disabled':''}>ก่อนหน้า</button><button class="btn" data-registry-page="${page+1}" ${page>=pages?'disabled':''}>ถัดไป</button></div></div></div>`;}

function registryDelete(id){const r=state.contractRegistry.find(x=>x.id===id);if(!r)return;confirmAction('ยืนยันลบสัญญา '+r.contract,'นำสัญญานี้ออกจากทะเบียนและสัปดาห์ใหม่ หากมีรายงานเดิม ระบบจะเก็บประวัติรายงานนั้นไว้',async()=>{await mutate('ลบสัญญา '+r.contract,s=>deleteRegistryRecord(s,id));});}
