export function miniSparklineSVG(values, stroke = '#10b981', fill = null) {
  if (!values || values.length < 2) return '';
  const min = Math.min(...values), max = Math.max(...values), range = max - min || 1;
  const pts = values.map((v, i) => (i * (60 / (values.length - 1))).toFixed(1) + ',' + (20 - ((v - min) / range) * 16 + 2).toFixed(1)).join(' ');
  const fillPath = fill ? `<polygon fill="${fill}" points="0,24 ${pts} 60,24"/>` : '';
  return `<svg class="mini-sparkline" viewBox="0 0 60 24" aria-hidden="true">${fillPath}<polyline fill="none" stroke="${stroke}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" points="${pts}"/></svg>`;
}
export function deltaBadge(delta, invert = false) {
  if (delta === 0) return '<span class="delta-badge neutral">0</span>';
  const isPos = delta > 0;
  const cls = (isPos !== invert) ? 'pos' : 'neg';
  const sign = isPos ? '+' : '';
  return `<span class="delta-badge ${cls}">${sign}${delta.toFixed(delta % 1 === 0 ? 0 : 1)}</span>`;
}

export function historyRowMatches(run,change,query='',kind='all'){
 const needle=String(query).trim().toLocaleLowerCase('th');
 return (!needle||[run.fileName,run.format,run.source,change.path].join(' ').toLocaleLowerCase('th').includes(needle))&&(kind==='all'||change.kind===({new:'added',updated:'updated',removed:'removed'}[kind]));
}

export function calcPipelineWeights(ongoing,deliver,pay,paid){
 const counts={ongoing,deliver,pay,paid},total=Object.values(counts).reduce((sum,n)=>sum+Math.max(0,Number(n)||0),0);
 return {...Object.fromEntries(Object.entries(counts).map(([key,n])=>[key,total?Math.max(0,Number(n)||0)*100/total:0])),expired:0};
}
export function financialSummary(records){
 const known=value=>value!==null&&value!==undefined&&value!==''&&Number.isFinite(Number(value));
 const sum=key=>records.reduce((total,r)=>total+(known(r[key])?Number(r[key]):0),0);
 const contractValue=sum('contractValue'),actualCost=sum('actualCost'),missing=records.filter(r=>!known(r.actualCost)).length;
 return {contractValue,actualCost,missing,known:records.length-missing,percent:contractValue>0?actualCost*100/contractValue:null};
}
